(894620, 103166, 15032, '<td valign="top">Very nice photo, but I think the blue channel is oversaturated</td>', 'Very nice photo, but I think the blue channel is oversaturated', '2004-09-06 01:04:07.000000', NULL, 1),
(894624, 102892, 15032, '<td valign="top">Interesting vantage point.  I like the color, but there is a lot of moire in this photo which is somewhat distracting</td>', 'Interesting vantage point.  I like the color, but there is a lot of moire in this photo which is somewhat distracting', '2004-09-06 01:04:57.000000', NULL, 1),
(894627, 103086, 15032, '<td valign="top">Great sky and overall color!</td>', 'Great sky and overall color!', '2004-09-06 01:05:13.000000', NULL, 1),
(894631, 102653, 15032, '<td valign="top">I think this photo could have had more impact in B/W to better use the contrast differences. Also, this appears to be somewhat oversharpened, especially wen looking at the leaves.</td>', 'I think this photo could have had more impact in B/W to better use the contrast differences. Also, this appears to be somewhat oversharpened, especially wen looking at the leaves.', '2004-09-06 01:06:09.000000', NULL, 1),
(894634, 101592, 15032, '<td valign="top">Nice and up close, I think converting this to B/W would have eliminated the color noise on the moon.</td>', 'Nice and up close, I think converting this to B/W would have eliminated the color noise on the moon.', '2004-09-06 01:06:54.000000', NULL, 1),
(894637, 102508, 15032, '<td valign="top">Excellent color, I think I would have liked to see a tighter crop on the top though</td>', 'Excellent color, I think I would have liked to see a tighter crop on the top though', '2004-09-06 01:07:32.000000', NULL, 1),
(894642, 102350, 15032, '<td valign="top">Excellent mood and lighting in this photo!  The reflections are excellent!</td>', 'Excellent mood and lighting in this photo!  The reflections are excellent!', '2004-09-06 01:09:24.000000', NULL, 1),
(894644, 103073, 14805, '<td valign="top">looks a little over sharpened, but otherwise an excellent photo.</td>', 'looks a little over sharpened, but otherwise an excellent photo.', '2004-09-06 01:09:49.000000', NULL, 1),
(894647, 103073, 15032, '<td valign="top">The water has a strange over-sharpened feel to it, but I like the overall color of the photo.</td>', 'The water has a strange over-sharpened feel to it, but I like the overall color of the photo.', '2004-09-06 01:10:07.000000', NULL, 1),
(894649, 103211, 15032, '<td valign="top">I think this photo is oversharpened as can be seen by the roof and the edges of the plants in the lower right hand corner of the photo.</td>', 'I think this photo is oversharpened as can be seen by the roof and the edges of the plants in the lower right hand corner of the photo.', '2004-09-06 01:10:45.000000', NULL, 1),
(894650, 102530, 15032, '<td valign="top">Very nice.  Possibly a little selective sharpening on the boat could have brought out a little more detail from the ropes without looking oversharpened as a whole.  Good shot!</td>', 'Very nice.  Possibly a little selective sharpening on the boat could have brought out a little more detail from the ropes without looking oversharpened as a whole.  Good shot!', '2004-09-06 01:11:39.000000', NULL, 1),
(894654, 103003, 15032, '<td valign="top">Great photo, but I''m not a big fan of the thick brown border.</td>', 'Great photo, but I''m not a big fan of the thick brown border.', '2004-09-06 01:12:46.000000', NULL, 1),
(894657, 102703, 15032, '<td valign="top">Nice overall photo, but the ring around the light is a little distracting</td>', 'Nice overall photo, but the ring around the light is a little distracting', '2004-09-06 01:13:12.000000', NULL, 1),
(894665, 103243, 15032, '<td valign="top">Good photo, but the vertical wires are a bit oversharpened- the moire is creating different colors that detract from the overall photo</td>', 'Good photo, but the vertical wires are a bit oversharpened- the moire is creating different colors that detract from the overall photo', '2004-09-06 01:14:33.000000', NULL, 1),
(894670, 101658, 9668, '<td valign="top">Title seems a little corny, but it is a beautiful shot. Would like to see more of the mountain to the  right, but still a good view of the city.</td>', 'Title seems a little corny, but it is a beautiful shot. Would like to see more of the mountain to the  right, but still a good view of the city.', '2004-09-06 01:16:15.000000', NULL, 1),
(894671, 102806, 7969, '<td valign="top">nice shot, but the format is a bit odd, would like to see it in a more traditional format.</td>', 'nice shot, but the format is a bit odd, would like to see it in a more traditional format.', '2004-09-06 01:16:19.000000', NULL, 1),
(894675, 102876, 7350, '<td valign="top">I think the sign could have been brightened up just a little, but the composition is fantastic. 7.</td>', 'I think the sign could have been brightened up just a little, but the composition is fantastic. 7.', '2004-09-06 01:17:02.000000', NULL, 1),
(894681, 103163, 7350, '<td valign="top">Including the boat really makes this fantastic.</td>', 'Including the boat really makes this fantastic.', '2004-09-06 01:19:06.000000', NULL, 1),
(894685, 103073, 7969, '<td valign="top">I think it is really oversharpened(distortions in clouds and tree tops), otherwise nice shot.</td>', 'I think it is really oversharpened(distortions in clouds and tree tops), otherwise nice shot.', '2004-09-06 01:20:26.000000', NULL, 1),
(894687, 102295, 19425, '<td valign="top">nice use of "Pop Artist", but this is a photo challenge, not how well you can convert it in PhotoShop</td>', 'nice use of "Pop Artist", but this is a photo challenge, not how well you can convert it in PhotoShop', '2004-09-06 01:20:57.000000', NULL, 1),
(894692, 102124, 11518, '<td valign="top">Unfortunately out of focus.  That''s a great location.  A tripod would have allowed you to produce a sharp image.</td>', 'Unfortunately out of focus.  That''s a great location.  A tripod would have allowed you to produce a sharp image.', '2004-09-06 01:22:35.000000', NULL, 1),
