(894701, 103198, 11518, '<td valign="top">A deeper DOF is needed to bring into focus the houses.  A smaller aperture would have helped achieve that.</td>', 'A deeper DOF is needed to bring into focus the houses.  A smaller aperture would have helped achieve that.', '2004-09-06 01:24:56.000000', NULL, 1),
(894702, 103051, 7969, '<td valign="top">This is a really nice shot, I wish the people were not looking out of the picture tho</td>', 'This is a really nice shot, I wish the people were not looking out of the picture tho', '2004-09-06 01:25:06.000000', NULL, 1),
(894705, 102677, 19425, '<td valign="top">good pic, its just that the rainbow just looks alittle to fake in my book...looks like  you added in photoshop to me....i have the same action.</td>', 'good pic, its just that the rainbow just looks alittle to fake in my book...looks like  you added in photoshop to me....i have the same action.', '2004-09-06 01:25:20.000000', NULL, 1),
(894706, 103263, 11518, '<td valign="top">Great location and light.  I would have preferred a less centered composition.  Showing either more sky or more water.  I think showing more water and maybe the beach would have worked better.</td>', 'Great location and light.  I would have preferred a less centered composition.  Showing either more sky or more water.  I think showing more water and maybe the beach would have worked better.', '2004-09-06 01:27:02.000000', NULL, 1),
(894707, 103197, 12253, '<td valign="top">Great choice of location from another capital districter... didn''t make it up there this year but I think there are more photogenic places there (in the park or town)!</td>', 'Great choice of location from another capital districter... didn''t make it up there this year but I think there are more photogenic places there (in the park or town)!', '2004-09-06 01:28:05.000000', NULL, 1),
(894709, 101801, 11518, '<td valign="top">Wow!  Beautiful shot.  Great timing, great light.  Great use of leading lines, perfect composition. My favourite so far! 10</td>', 'Wow!  Beautiful shot.  Great timing, great light.  Great use of leading lines, perfect composition. My favourite so far! 10', '2004-09-06 01:28:42.000000', NULL, 1),
