(894714, 103102, 11518, '<td valign="top">Beautiful shot and location.  Very good light.  Unfortunately I see a halo around the statue, probably from oversharpening.</td>', 'Beautiful shot and location.  Very good light.  Unfortunately I see a halo around the statue, probably from oversharpening.', '2004-09-06 01:31:09.000000', NULL, 1),
(894715, 102677, 11518, '<td valign="top">You could have cropped more of the bottom part.</td>', 'You could have cropped more of the bottom part.', '2004-09-06 01:31:43.000000', NULL, 1),
