(894719, 102518, 11518, '<td valign="top">Beautiful.  A tad overexposed though. A  -1.5 to -2  exposure compensation would probably have worked better.</td>', 'Beautiful.  A tad overexposed though. A  -1.5 to -2  exposure compensation would probably have worked better.', '2004-09-06 01:33:33.000000', NULL, 1),
(894723, 102332, 11518, '<td valign="top">Beautiful shot.  Maybe a tad over-saturated</td>', 'Beautiful shot.  Maybe a tad over-saturated', '2004-09-06 01:36:41.000000', NULL, 1),
(894725, 103003, 11518, '<td valign="top">Beautiful location.  A different time of day would have possibly produced a better looking sky. 7</td>', 'Beautiful location.  A different time of day would have possibly produced a better looking sky. 7', '2004-09-06 01:38:30.000000', NULL, 1),
(894730, 102007, 25183, '<td valign="top">wow!!  I don''t know what else to say, but wow!!  Impressive colors, my eyes float right across the photo as the clouds appear to be doing.  I love the little tree standing alone.  Just...wow!  I''m not a member and have never commented on a member challenge...if it gives me the option to rate this, you will see a 10 from me!</td>', 'wow!!  I don''t know what else to say, but wow!!  Impressive colors, my eyes float right across the photo as the clouds appear to be doing.  I love the little tree standing alone.  Just...wow!  I''m not a member and have never commented on a member challenge...if it gives me the option to rate this, you will see a 10 from me!', '2004-09-06 01:44:41.000000', NULL, 1),
(894731, 103086, 12962, '<td valign="top">I love San Diego and I love this photograph.  The sky is particularly amazing and the action is palpalbe even to the minutest detail.  I just wish the Padres will win (wishful thinking I guess).  Hope you do well (again, I think).</td>', 'I love San Diego and I love this photograph.  The sky is particularly amazing and the action is palpalbe even to the minutest detail.  I just wish the Padres will win (wishful thinking I guess).  Hope you do well (again, I think).', '2004-09-06 01:45:05.000000', NULL, 1),
(894735, 103240, 12962, '<td valign="top">Nice.  I like the creamy appearance of the water.  Hope you can do a tutorial how to achieve a texture like this.</td>', 'Nice.  I like the creamy appearance of the water.  Hope you can do a tutorial how to achieve a texture like this.', '2004-09-06 01:46:36.000000', NULL, 1),
