(894984, 103211, 25464, '<td valign="top">Nice composition.  Looks a bit over-sharpened and the color needs to be adjusted. Good.</td>', 'Nice composition.  Looks a bit over-sharpened and the color needs to be adjusted. Good.', '2004-09-06 03:34:58.000000', NULL, 1),
(894989, 102007, 16241, '<td valign="top">sooo pretty</td>', 'sooo pretty', '2004-09-06 03:36:23.000000', NULL, 1),
(894991, 102769, 15032, '<td valign="top">Nice shot! I would have gone for a little tighter crop though.</td>', 'Nice shot! I would have gone for a little tighter crop though.', '2004-09-06 03:37:21.000000', NULL, 1),
(894992, 103231, 12962, '<td valign="top">I didn''t know about this.  If I have seen your photograph before I went to the falls last year, I would have certainly doen this.  Your perspective is wonderful, your colors are great and it was the right time of the day to take this.  Hope you do well.</td>', 'I didn''t know about this.  If I have seen your photograph before I went to the falls last year, I would have certainly doen this.  Your perspective is wonderful, your colors are great and it was the right time of the day to take this.  Hope you do well.', '2004-09-06 03:37:22.000000', NULL, 1),
(894993, 102676, 12962, '<td valign="top">Beautiful composition.</td>', 'Beautiful composition.', '2004-09-06 03:37:34.000000', NULL, 1),
(894994, 102267, 15032, '<td valign="top">Excellent! Great color and contrast!</td>', 'Excellent! Great color and contrast!', '2004-09-06 03:38:01.000000', NULL, 1),
(894995, 102258, 25464, '<td valign="top">I am not sure about your choice in color editing.  It definitely makes this one stand out, but I don''t ever remember seeing anything edited this way in a travel magazine.  Good shot.</td>', 'I am not sure about your choice in color editing.  It definitely makes this one stand out, but I don''t ever remember seeing anything edited this way in a travel magazine.  Good shot.', '2004-09-06 03:39:17.000000', NULL, 1),
(894996, 103084, 15032, '<td valign="top">Wow!  A little moire on the vertical windows, but other than that, exellent!</td>', 'Wow!  A little moire on the vertical windows, but other than that, exellent!', '2004-09-06 03:39:34.000000', NULL, 1),
(895004, 101592, 25464, '<td valign="top">This would be even more stunning with a red tint.</td>', 'This would be even more stunning with a red tint.', '2004-09-06 03:45:49.000000', NULL, 1),
(895005, 103006, 15032, '<td valign="top">Would have worked well in the framing challenge as well!</td>', 'Would have worked well in the framing challenge as well!', '2004-09-06 03:46:00.000000', NULL, 1),
