INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(895066, 102546, 25017, '<td valign="top">would like to see this in colour or full b&amp;w but lovely!</td>', 'would like to see this in colour or full b&w but lovely!', '2004-09-06 04:42:03.000000', NULL, 1),
(895067, 102792, 8054, '<td valign="top">Never been to RI myself but this is a very nice cityscape shot. Deep blue skies and nice details of the buildings and clouds. And my favorite feature: the ginster yellow GTI. Now I don''t know how much the GTI has to do with this photo or any specific car in general for that matter but this is a nice general photo.</td>', 'Never been to RI myself but this is a very nice cityscape shot. Deep blue skies and nice details of the buildings and clouds. And my favorite feature: the ginster yellow GTI. Now I don''t know how much the GTI has to do with this photo or any specific car in general for that matter but this is a nice general photo.', '2004-09-06 04:42:26.000000', NULL, 1),
(895071, 102642, 8054, '<td valign="top">Excellent perspective that also includes the fountain. Composition is very good. Focus is fairly consistent throughout. The one issue that could use work is contrast. It''s fairly flat and could use some adjustment with the use of levels and/or curves.</td>', 'Excellent perspective that also includes the fountain. Composition is very good. Focus is fairly consistent throughout. The one issue that could use work is contrast. It''s fairly flat and could use some adjustment with the use of levels and/or curves.', '2004-09-06 04:46:25.000000', NULL, 1),
(895074, 102904, 8054, '<td valign="top">A very nice photo but I would like to give more points if this had specific meaning to this building. In other words, is this figure symbolic of something? If there are any impotant details I would have liked to see them in the title somehow. Otherwise, I see this simply as a male figure with a globe(?) on his back. Might be Atlas but I cannot tell.</td>', 'A very nice photo but I would like to give more points if this had specific meaning to this building. In other words, is this figure symbolic of something? If there are any impotant details I would have liked to see them in the title somehow. Otherwise, I see this simply as a male figure with a globe(?) on his back. Might be Atlas but I cannot tell.', '2004-09-06 04:49:36.000000', NULL, 1),
(895075, 103102, 4767, '<td valign="top">VERY nice viewpoint on this garden!  Great sky, lots of excellent detail.  (Is Thanksgiving Point Gardens a great secret or what?)</td>', 'VERY nice viewpoint on this garden!  Great sky, lots of excellent detail.  (Is Thanksgiving Point Gardens a great secret or what?)', '2004-09-06 04:50:16.000000', NULL, 1),
(895085, 102812, 8054, '<td valign="top">This is one of my top choices for a ribbon for sure. Love the strong contrast between the tree and the volumetric lighting of the sky. Just seems a smidge dark but excellent photo. 10</td>', 'This is one of my top choices for a ribbon for sure. Love the strong contrast between the tree and the volumetric lighting of the sky. Just seems a smidge dark but excellent photo. 10', '2004-09-06 05:01:58.000000', NULL, 1),
(895086, 103193, 17072, '<td valign="top">Very Nice</td>', 'Very Nice', '2004-09-06 05:04:34.000000', NULL, 1),
(895087, 103042, 17072, '<td valign="top">Beautiful</td>', 'Beautiful', '2004-09-06 05:04:50.000000', NULL, 1),
(895088, 103122, 17072, '<td valign="top">Lovely</td>', 'Lovely', '2004-09-06 05:04:57.000000', NULL, 1),
(895089, 103255, 25017, '<td valign="top">simpley beautfiul wish the sun was not quite so bright and love the figure in the distance</td>', 'simpley beautfiul wish the sun was not quite so bright and love the figure in the distance', '2004-09-06 05:05:06.000000', NULL, 1),
(895090, 101772, 17072, '<td valign="top">Nicely done!</td>', 'Nicely done!', '2004-09-06 05:05:07.000000', NULL, 1),
(895091, 103224, 17072, '<td valign="top">Amazing</td>', 'Amazing', '2004-09-06 05:05:14.000000', NULL, 1),
(895092, 102168, 25017, '<td valign="top">magnificent photo - well done!</td>', 'magnificent photo - well done!', '2004-09-06 05:05:31.000000', NULL, 1),
(895093, 102123, 8054, '<td valign="top">Good choice going with duotone with this photo. It seems to add to the feel that the building is old and historic. The use of the bridge/walkway to lead the eyes to the building is also good. It''s hard to tell if the building is actually that way or if contrast is an issue. It seems that the chimney is a bit overexposed but it''s probably that way. 9</td>', 'Good choice going with duotone with this photo. It seems to add to the feel that the building is old and historic. The use of the bridge/walkway to lead the eyes to the building is also good. It''s hard to tell if the building is actually that way or if contrast is an issue. It seems that the chimney is a bit overexposed but it''s probably that way. 9', '2004-09-06 05:06:20.000000', NULL, 1),
(895094, 101704, 17072, '<td valign="top">Not sure I like the desaturation in this</td>', 'Not sure I like the desaturation in this', '2004-09-06 05:06:32.000000', NULL, 1),
(895095, 102123, 17072, '<td valign="top">Nice shot</td>', 'Nice shot', '2004-09-06 05:06:55.000000', NULL, 1),
(895096, 103201, 17072, '<td valign="top">pretty shot</td>', 'pretty shot', '2004-09-06 05:07:55.000000', NULL, 1),
(895097, 103197, 17072, '<td valign="top">Nice</td>', 'Nice', '2004-09-06 05:08:05.000000', NULL, 1),
(895099, 103156, 17072, '<td valign="top">nice building</td>', 'nice building', '2004-09-06 05:08:40.000000', NULL, 1),
(895100, 103051, 25017, '<td valign="top">lovely composition, the sky is awesome</td>', 'lovely composition, the sky is awesome', '2004-09-06 05:09:24.000000', NULL, 1),
(895101, 102876, 17072, '<td valign="top">Pretty shot</td>', 'Pretty shot', '2004-09-06 05:09:41.000000', NULL, 1),
(895103, 102332, 17072, '<td valign="top">Very pretty</td>', 'Very pretty', '2004-09-06 05:10:08.000000', NULL, 1),
(895104, 103160, 17072, '<td valign="top">I could see this in a guide</td>', 'I could see this in a guide', '2004-09-06 05:10:49.000000', NULL, 1),
(895105, 102117, 17072, '<td valign="top">Love this shot</td>', 'Love this shot', '2004-09-06 05:11:16.000000', NULL, 1),
(895106, 103220, 17072, '<td valign="top">BEAUTIFUL!!!!!</td>', 'BEAUTIFUL!!!!!', '2004-09-06 05:11:37.000000', NULL, 1),
(895107, 101995, 17072, '<td valign="top">Where is this??? it''s great!</td>', 'Where is this??? it''s great!', '2004-09-06 05:11:57.000000', NULL, 1),
(895108, 102007, 8054, '<td valign="top">Very impressive composition bordering on minimalist with just the tree. The sky is distracting with the very dark portion above the cloud and the lighter part below. I think that will hurt this photo the most.</td>', 'Very impressive composition bordering on minimalist with just the tree. The sky is distracting with the very dark portion above the cloud and the lighter part below. I think that will hurt this photo the most.', '2004-09-06 05:12:15.000000', NULL, 1),
(895109, 101475, 17072, '<td valign="top">nice</td>', 'nice', '2004-09-06 05:12:23.000000', NULL, 1),
(895110, 102677, 17072, '<td valign="top">great shot</td>', 'great shot', '2004-09-06 05:13:44.000000', NULL, 1),
(895111, 103012, 17072, '<td valign="top">wow!</td>', 'wow!', '2004-09-06 05:14:20.000000', NULL, 1),
(895112, 102117, 25840, '<td valign="top">Pretty awesome!  Precisely the right moment!</td>', 'Pretty awesome!  Precisely the right moment!', '2004-09-06 05:14:24.000000', NULL, 1),
(895114, 103223, 17072, '<td valign="top">Goat Island? Nice shot.</td>', 'Goat Island? Nice shot.', '2004-09-06 05:15:37.000000', NULL, 1),
(895116, 103262, 17072, '<td valign="top">Beautiful</td>', 'Beautiful', '2004-09-06 05:17:05.000000', NULL, 1),
(895117, 103241, 17072, '<td valign="top">Nice pic for a guide.</td>', 'Nice pic for a guide.', '2004-09-06 05:17:23.000000', NULL, 1),
(895118, 102350, 8643, '<td valign="top">Very picturesque, nice balance through an excellent vantage point, caught at just the right moment for light.  Would have preferred it without a border.  Still one of the best.</td>', 'Very picturesque, nice balance through an excellent vantage point, caught at just the right moment for light.  Would have preferred it without a border.  Still one of the best.', '2004-09-06 05:20:53.000000', NULL, 1),
(895126, 102985, 14656, '<td valign="top">Good angle/perspective.. It''s too bad the sky is blown out. Nice photo but it doesn''t convey the sense of shopping to me. Maybe if they were carrying shopping bags or were near a display window.</td>', 'Good angle/perspective.. It''s too bad the sky is blown out. Nice photo but it doesn''t convey the sense of shopping to me. Maybe if they were carrying shopping bags or were near a display window.', '2004-09-06 05:37:53.000000', NULL, 1),
(895128, 102117, 14656, '<td valign="top">Excellent color although I could never imagine the sky being that shade of purple. Normally I''d say the birds are a distraction but since there are so many of them, it''s a welcomed addition and makes it seems more like a tourist or gathering spot.</td>', 'Excellent color although I could never imagine the sky being that shade of purple. Normally I''d say the birds are a distraction but since there are so many of them, it''s a welcomed addition and makes it seems more like a tourist or gathering spot.', '2004-09-06 05:39:34.000000', NULL, 1),
(895131, 102719, 14656, '<td valign="top">Nice subtle DOF. Good composition. Beautiful photo, just wish there was more landscape in the background or a glimpse of the ocean.</td>', 'Nice subtle DOF. Good composition. Beautiful photo, just wish there was more landscape in the background or a glimpse of the ocean.', '2004-09-06 05:41:40.000000', NULL, 1),
(895132, 102284, 14656, '<td valign="top">Not sure how this image would make me want to visit this place. Appears to be the entrance to a park in the city. A tourist spot should attract visitors by showing them something scenic or distinguishable they don''t have.. otherwise they''d never leave home.</td>', 'Not sure how this image would make me want to visit this place. Appears to be the entrance to a park in the city. A tourist spot should attract visitors by showing them something scenic or distinguishable they don''t have.. otherwise they''d never leave home.', '2004-09-06 05:45:27.000000', NULL, 1),
(895134, 102811, 14656, '<td valign="top">Nice blurring of the background but I wish the glass on the table (middleground) were in focus too, but that could just be personal preference. Light from flash a little bright, creating harsh shadow between hands. A bounced or diffused flash would''ve worked nicely.</td>', 'Nice blurring of the background but I wish the glass on the table (middleground) were in focus too, but that could just be personal preference. Light from flash a little bright, creating harsh shadow between hands. A bounced or diffused flash would''ve worked nicely.', '2004-09-06 05:47:20.000000', NULL, 1),
(895136, 103015, 14656, '<td valign="top">I was going to comment on the dull gray sky but then realized from the Space Needle and the title "Seattle" that this is how it''s supposed to look!  I think I would''ve framed a little less at the bottom and a little more at the top but it could''ve been your intent to cut out the drabness. Nice shot, makes me miss Seatown.</td>', 'I was going to comment on the dull gray sky but then realized from the Space Needle and the title "Seattle" that this is how it''s supposed to look!  I think I would''ve framed a little less at the bottom and a little more at the top but it could''ve been your intent to cut out the drabness. Nice shot, makes me miss Seatown.', '2004-09-06 05:49:24.000000', NULL, 1),
(895137, 101818, 14656, '<td valign="top">After a few moments, I realized this was for London. Image seems a little soft on the focus. Nice image but kind of busy to look at.</td>', 'After a few moments, I realized this was for London. Image seems a little soft on the focus. Nice image but kind of busy to look at.', '2004-09-06 05:50:49.000000', NULL, 1),
(895140, 102381, 14656, '<td valign="top">Whites are a little overexposed. Is this a residential area? I would''ve focused less on the houses and more on the ocean/landscape.</td>', 'Whites are a little overexposed. Is this a residential area? I would''ve focused less on the houses and more on the ocean/landscape.', '2004-09-06 05:52:13.000000', NULL, 1),
(895143, 102422, 14656, '<td valign="top">I like how the eyes follow the line of the horses and cattle. Background seems a bit random to me but maybe because I don''t expect to be seeing these animals on the street?</td>', 'I like how the eyes follow the line of the horses and cattle. Background seems a bit random to me but maybe because I don''t expect to be seeing these animals on the street?', '2004-09-06 05:53:46.000000', NULL, 1),
(895144, 103163, 14656, '<td valign="top">Sunset shots are hard when pointing the camera at the sun. The background tends to get underexposed as in this case, forcing everything into silhouettes and darkness. Did you try dodging the image to bring back some highlights?</td>', 'Sunset shots are hard when pointing the camera at the sun. The background tends to get underexposed as in this case, forcing everything into silhouettes and darkness. Did you try dodging the image to bring back some highlights?', '2004-09-06 05:55:32.000000', NULL, 1),
(895146, 102530, 14656, '<td valign="top">Great image, considered doing a similar shot as well. The bottom of the boat is pretty close to the bottom of the photo and the masts are cut off but I''m assuming because you didn''t have a wide enough angle. Sky appears a little underexposed. Colors here aren''t that amazing, did you try b&amp;w?</td>', 'Great image, considered doing a similar shot as well. The bottom of the boat is pretty close to the bottom of the photo and the masts are cut off but I''m assuming because you didn''t have a wide enough angle. Sky appears a little underexposed. Colors here aren''t that amazing, did you try b&w?', '2004-09-06 05:58:01.000000', NULL, 1),
(895147, 102808, 24778, '<td valign="top">imperial ass... sorry but couldn''t help... very nice photo and gracefully done... but the shape of the roof makes the sky+clouds looks like an butt. too bad I cannot rate (not a member yet) because it would get a high rating from me... keep it going</td>', 'imperial ass... sorry but couldn''t help... very nice photo and gracefully done... but the shape of the roof makes the sky+clouds looks like an butt. too bad I cannot rate (not a member yet) because it would get a high rating from me... keep it going', '2004-09-06 05:58:54.000000', NULL, 1),
(895150, 102899, 14656, '<td valign="top">I think you could''ve cropped a little off the bottom as that much rock in the foreground is a little unnecessary. I would''ve also divided the image into thirds, consisting of foreground, middleground, and background/sky. I like the hues in the sky but unfortunately, the rocks and light reflecting off the water are pretty drab. A polarizer might''ve helped this shot.</td>', 'I think you could''ve cropped a little off the bottom as that much rock in the foreground is a little unnecessary. I would''ve also divided the image into thirds, consisting of foreground, middleground, and background/sky. I like the hues in the sky but unfortunately, the rocks and light reflecting off the water are pretty drab. A polarizer might''ve helped this shot.', '2004-09-06 06:00:28.000000', NULL, 1),
(895152, 102679, 14656, '<td valign="top">Nice color. Wish the boat were larger or closer to the foreground to reaffirm the notion of "fishing." Here, it just looks like a boat happened to be in the background. I think I would''ve shifted the framing a little more to the right, showing less land/trees, and more water.</td>', 'Nice color. Wish the boat were larger or closer to the foreground to reaffirm the notion of "fishing." Here, it just looks like a boat happened to be in the background. I think I would''ve shifted the framing a little more to the right, showing less land/trees, and more water.', '2004-09-06 06:02:36.000000', NULL, 1),
(895153, 102746, 14656, '<td valign="top">Horizon is tilted. Also wish the bottom of the inner tube wasn''t cut off. Good idea, just not very successful at holding attention or attracting visitors I''m afraid.</td>', 'Horizon is tilted. Also wish the bottom of the inner tube wasn''t cut off. Good idea, just not very successful at holding attention or attracting visitors I''m afraid.', '2004-09-06 06:04:01.000000', NULL, 1),
(895155, 103265, 14656, '<td valign="top">Nice exposure and love the reflection on the water. That has got to be the finest City Hall I''ve ever seen. Great composition.</td>', 'Nice exposure and love the reflection on the water. That has got to be the finest City Hall I''ve ever seen. Great composition.', '2004-09-06 06:05:30.000000', NULL, 1),
(895156, 103162, 14656, '<td valign="top">This image reminds me of a postcard. Wish the tip of the roof wasn''t cut off. A slightly wider angle would''ve been nice.</td>', 'This image reminds me of a postcard. Wish the tip of the roof wasn''t cut off. A slightly wider angle would''ve been nice.', '2004-09-06 06:06:18.000000', NULL, 1),
(895158, 103263, 14656, '<td valign="top">Beautiful. Reminds me of "The Goonies." Colors are also very subtle and even appear desaturated which I think forces the viewer to pay more attention to the composition. I probably would''ve made the colors explode and lose the viewer''s interest in the rocks. Great job.</td>', 'Beautiful. Reminds me of "The Goonies." Colors are also very subtle and even appear desaturated which I think forces the viewer to pay more attention to the composition. I probably would''ve made the colors explode and lose the viewer''s interest in the rocks. Great job.', '2004-09-06 06:08:19.000000', NULL, 1),
(895160, 102973, 14656, '<td valign="top">I like how the leaves in the upper left point to the windmill. Very pleasing image. Shadow on the dirt road could''ve been cloned out.</td>', 'I like how the leaves in the upper left point to the windmill. Very pleasing image. Shadow on the dirt road could''ve been cloned out.', '2004-09-06 06:09:44.000000', NULL, 1),
(895162, 102677, 14656, '<td valign="top">Beautifully intense rainbow. Shadow at the base of sculpture not very pleasing. Still looking at the brilliance of the rainbow which steals attention away from the foreground, making it almost seem as if the statue was just placed in the picture for no reason.</td>', 'Beautifully intense rainbow. Shadow at the base of sculpture not very pleasing. Still looking at the brilliance of the rainbow which steals attention away from the foreground, making it almost seem as if the statue was just placed in the picture for no reason.', '2004-09-06 06:11:34.000000', NULL, 1),
(895163, 103122, 14656, '<td valign="top">Nice range of tones in the sky. I think I would''ve boosted the midtones just a little higher to soften some of the pure black in the bottom right and silhouette of the land.</td>', 'Nice range of tones in the sky. I think I would''ve boosted the midtones just a little higher to soften some of the pure black in the bottom right and silhouette of the land.', '2004-09-06 06:13:06.000000', NULL, 1),
(895164, 103238, 14656, '<td valign="top">The tree appears totally random for no apparent reason. I think I would''ve gone a few steps closer so the bottom of the last stair was at the bottom of the frame. I like the juxtaposition of the stairs leading up to the brightness and the other set going into darkness. Image could also be rotated CCW 1°</td>', 'The tree appears totally random for no apparent reason. I think I would''ve gone a few steps closer so the bottom of the last stair was at the bottom of the frame. I like the juxtaposition of the stairs leading up to the brightness and the other set going into darkness. Image could also be rotated CCW 1°', '2004-09-06 06:14:59.000000', NULL, 1),
(895167, 102892, 14656, '<td valign="top">Interesting angle, but just a little too slanted to portray a building. The ArtsPost sign is also cut off and the sky washed out.</td>', 'Interesting angle, but just a little too slanted to portray a building. The ArtsPost sign is also cut off and the sky washed out.', '2004-09-06 06:16:20.000000', NULL, 1),
(895173, 103102, 14656, '<td valign="top">The appearance of black outlines around the trees and halo around the sculpture appear to be from oversharpening. I like the detail in the fountain but the background I find distracting. I think you could''ve also placed the statue all the way in the corner of the upper right of the frame.</td>', 'The appearance of black outlines around the trees and halo around the sculpture appear to be from oversharpening. I like the detail in the fountain but the background I find distracting. I think you could''ve also placed the statue all the way in the corner of the upper right of the frame.', '2004-09-06 06:19:01.000000', NULL, 1),
(895175, 102792, 14656, '<td valign="top">Great shot. Too bad the trees on the left and the traffic light pole I find distracting. Also wish the yellow car at the bottom wasn''t cut off.</td>', 'Great shot. Too bad the trees on the left and the traffic light pole I find distracting. Also wish the yellow car at the bottom wasn''t cut off.', '2004-09-06 06:20:24.000000', NULL, 1),
(895179, 102405, 14656, '<td valign="top">Image cropped a little closely to the sides. I think this photo begs for landscape orientation. It''s a shame, I''d like to have seen more of the garden and fountain but I suppose the subject of your photo was the globe. In that case, I would''ve cut off the plants and grass at the bottom but that''s just me.</td>', 'Image cropped a little closely to the sides. I think this photo begs for landscape orientation. It''s a shame, I''d like to have seen more of the garden and fountain but I suppose the subject of your photo was the globe. In that case, I would''ve cut off the plants and grass at the bottom but that''s just me.', '2004-09-06 06:22:59.000000', NULL, 1),
(895180, 102700, 14656, '<td valign="top">Too much negative space (even if this was for the "Framing" challenge) and I don''t find this to be an interesting subject.</td>', 'Too much negative space (even if this was for the "Framing" challenge) and I don''t find this to be an interesting subject.', '2004-09-06 06:24:19.000000', NULL, 1),
(895182, 101658, 14656, '<td valign="top">Wow, great view of the city. The mountain (sorry, I suck at Geography) is a great touch. Focus appears to be locked on the trees in the foreground, making the buildings slightly soft on the focus.</td>', 'Wow, great view of the city. The mountain (sorry, I suck at Geography) is a great touch. Focus appears to be locked on the trees in the foreground, making the buildings slightly soft on the focus.', '2004-09-06 06:26:23.000000', NULL, 1),
