INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(896057, 103065, 26044, '<td valign="top">this is just hot.  nice timing</td>', 'this is just hot.  nice timing', '2004-09-06 17:35:50.000000', NULL, 1),
(896067, 102416, 17300, '<td valign="top">Wonderful. 10</td>', 'Wonderful. 10', '2004-09-06 17:42:07.000000', NULL, 1),
(896068, 101995, 17300, '<td valign="top">A great one.... 10 from me. Makes me wonder - if I saw it, could I capture it?</td>', 'A great one.... 10 from me. Makes me wonder - if I saw it, could I capture it?', '2004-09-06 17:43:11.000000', NULL, 1),
(896071, 103012, 17300, '<td valign="top">9 from me. There have been a lot of great photos in this contest, but I think this is one among 10 or 15 or so that really has captured sights that would make it into a guide...</td>', '9 from me. There have been a lot of great photos in this contest, but I think this is one among 10 or 15 or so that really has captured sights that would make it into a guide...', '2004-09-06 17:44:52.000000', NULL, 1),
(896073, 101801, 17300, '<td valign="top">Lovely shot. Don''t think it would have made it into a travel guide, though. Still a 9 from me.<br/>Comment nr 2: this one keeps getting back to me... OK - a 10... But I still don''t see t in a travel guide...<br/></td>', 'Lovely shot. Don''t think it would have made it into a travel guide, though. Still a 9 from me.Comment nr 2: this one keeps getting back to me... OK - a 10... But I still don''t see t in a travel guide...', '2004-09-06 17:46:08.000000', NULL, 1),
(896074, 102638, 17300, '<td valign="top">Definately something you would find in a travel guide, but maybe in a different light and setting somehow. A nice one anyway</td>', 'Definately something you would find in a travel guide, but maybe in a different light and setting somehow. A nice one anyway', '2004-09-06 17:48:16.000000', NULL, 1),
(896080, 102447, 17300, '<td valign="top">Snygg och välgjord bild av vår kära huvudsta där uppe i norr... Egentligen enda invändningen är valet av motiv -är det rätt bild som representerar Stockholm, kvällstid? Kanske inte, men grattis till en bra bild...</td>', 'Snygg och välgjord bild av vår kära huvudsta där uppe i norr... Egentligen enda invändningen är valet av motiv -är det rätt bild som representerar Stockholm, kvällstid? Kanske inte, men grattis till en bra bild...', '2004-09-06 17:52:05.000000', NULL, 1),
(896090, 102999, 17300, '<td valign="top">Cool one, but only attractive to a small number of people, i.e. the ones who''d buy "The Storm Chaser''s Guide to ....?"<br/>Looks cold and wet...</td>', 'Cool one, but only attractive to a small number of people, i.e. the ones who''d buy "The Storm Chaser''s Guide to ....?"Looks cold and wet...', '2004-09-06 17:57:16.000000', NULL, 1),
(896117, 102124, 7743, '<td valign="top">In most cases it is beneficial to have the object in the forground (tall grass) in focus, however, your background object (silo) has more presence in this image and having it out of focus is very distracting.  A slightly different viewpoint  to include less of the tall grass I belief would also make this photo better.  Nice eye for the sky even if it is obscured by the silo.</td>', 'In most cases it is beneficial to have the object in the forground (tall grass) in focus, however, your background object (silo) has more presence in this image and having it out of focus is very distracting.  A slightly different viewpoint  to include less of the tall grass I belief would also make this photo better.  Nice eye for the sky even if it is obscured by the silo.', '2004-09-06 18:08:44.000000', NULL, 1),
(896125, 103262, 18080, '<td valign="top">Great shot.<br/>A big 10 from me.<br/>Love the colours<br/>Love the way the tree walks you right through the shot.<br/>If there is any sanity in the world, this will take the blue.<br/>Good luck</td>', 'Great shot.A big 10 from me.Love the coloursLove the way the tree walks you right through the shot.If there is any sanity in the world, this will take the blue.Good luck', '2004-09-06 18:13:24.000000', NULL, 1),
(896126, 103154, 18080, '<td valign="top">Great image<br/>10</td>', 'Great image10', '2004-09-06 18:13:44.000000', NULL, 1),
(896128, 103263, 18080, '<td valign="top">I originally marked this a 9<br/>But i see no reason for knocking a point of this perfect shot.<br/>10 from me.<br/>Good luck</td>', 'I originally marked this a 9But i see no reason for knocking a point of this perfect shot.10 from me.Good luck', '2004-09-06 18:14:51.000000', NULL, 1),
(896132, 103102, 22781, '<td valign="top">Voted around 40% allready, this is my 1st WOW! I just don''t believe your sky color :)<br/>Update, your one of my 2 top picks!</td>', 'Voted around 40% allready, this is my 1st WOW! I just don''t believe your sky color :)Update, your one of my 2 top picks!', '2004-09-06 18:21:00.000000', NULL, 1),
(896157, 102007, 4871, '<td valign="top">An exquisite picture! Beautifully composed. I''m assuming that it was the terrain, but there is a slight tilt of the horizion,  but I don''t think it detracts from the scene too much.</td>', 'An exquisite picture! Beautifully composed. I''m assuming that it was the terrain, but there is a slight tilt of the horizion,  but I don''t think it detracts from the scene too much.', '2004-09-06 18:34:57.000000', NULL, 1),
(896164, 102887, 4871, '<td valign="top">I think this is a fantastic photograph, but to me it isn''t really advertising a particular area. This shot could be any pier. Keep it up though - I really like the shot.</td>', 'I think this is a fantastic photograph, but to me it isn''t really advertising a particular area. This shot could be any pier. Keep it up though - I really like the shot.', '2004-09-06 18:39:09.000000', NULL, 1),
(896182, 102642, 4871, '<td valign="top">This picture seems almost surreal - I love the frame and the clouds really set this picture! One of the highest scores I''ve given for this pic!</td>', 'This picture seems almost surreal - I love the frame and the clouds really set this picture! One of the highest scores I''ve given for this pic!', '2004-09-06 18:47:23.000000', NULL, 1),
(896184, 103164, 93, '<td valign="top">I really like the cropping and POV on this photo, and having the couple in the foreground really helps sell it for the theme. <br/>I find it a tad dark and perhaps a little flat, but a really nice shot. Good job.</td>', 'I really like the cropping and POV on this photo, and having the couple in the foreground really helps sell it for the theme. I find it a tad dark and perhaps a little flat, but a really nice shot. Good job.', '2004-09-06 18:48:15.000000', NULL, 1),
(896186, 103247, 4871, '<td valign="top">I really like where you were heading with this pic (no pun intended) but, especially due to the title, I would have liked to see the road stretching off into the distance - it would have been the subject in your photograph. I believe that every picture needs a subject to draw attention and create the ''wow'' factor - this is the element that seems to be lacking in this one. The cloud formations are amazing! You''ve captured these very well!!!</td>', 'I really like where you were heading with this pic (no pun intended) but, especially due to the title, I would have liked to see the road stretching off into the distance - it would have been the subject in your photograph. I believe that every picture needs a subject to draw attention and create the ''wow'' factor - this is the element that seems to be lacking in this one. The cloud formations are amazing! You''ve captured these very well!!!', '2004-09-06 18:50:21.000000', NULL, 1),
(896188, 102774, 93, '<td valign="top">This is something I''d expect to find on the cover of *any* Quebec City brochure or travel magazine..  It''s a wonderfully lit shot with gorgeous tones and the perfect feel for this "wintery" city.. known for it''s annual winter festival.<br/> <br/>The wall draws the viewer into the scene and the sunset and lights on the chateau whisk you into the destination.  My favorite shot of the challenge. Great work!</td>', 'This is something I''d expect to find on the cover of *any* Quebec City brochure or travel magazine..  It''s a wonderfully lit shot with gorgeous tones and the perfect feel for this "wintery" city.. known for it''s annual winter festival. The wall draws the viewer into the scene and the sunset and lights on the chateau whisk you into the destination.  My favorite shot of the challenge. Great work!', '2004-09-06 18:50:36.000000', NULL, 1),
(896189, 103240, 16148, '<td valign="top">Great shot!  I like the single centered cloud and stone.  The shore line and horizon have interesting symmetric patterns.  There is a small cloud on the right edge that I would have cropped or edited out.  Good luck.<br/><br/><i>Message edited by author 2006-05-11 08:15:07.</i></td>', 'Great shot!  I like the single centered cloud and stone.  The shore line and horizon have interesting symmetric patterns.  There is a small cloud on the right edge that I would have cropped or edited out.  Good luck.', '2004-09-06 18:50:42.000000', '2006-05-11 09:15:07.000000', 1),
(896192, 102165, 93, '<td valign="top">I find this to be an absolutely *wonderful* POV.. lifting this shot above many of the others of similar style in the challenge.   great eye.</td>', 'I find this to be an absolutely *wonderful* POV.. lifting this shot above many of the others of similar style in the challenge.   great eye.', '2004-09-06 18:52:12.000000', NULL, 1),
(896195, 103259, 93, '<td valign="top">I really love the POV on this shot, but do have a couple of suggestions.  I find the contrast to be a little flat, which doesn''t flatter the sculpture, blending it in a little too much with the background.  Also, I think the tilt of the building in regards to your framing is a touch off.   I love that you''ve been able to capture the subject so crisply in the obviously low lighting.</td>', 'I really love the POV on this shot, but do have a couple of suggestions.  I find the contrast to be a little flat, which doesn''t flatter the sculpture, blending it in a little too much with the background.  Also, I think the tilt of the building in regards to your framing is a touch off.   I love that you''ve been able to capture the subject so crisply in the obviously low lighting.', '2004-09-06 18:54:53.000000', NULL, 1),
(896197, 103064, 93, '<td valign="top">A very nice take on the challenge.  The blue tones in the lighting really compliment the chrome of the compass IMO, and great detail on the actual mechanics.</td>', 'A very nice take on the challenge.  The blue tones in the lighting really compliment the chrome of the compass IMO, and great detail on the actual mechanics.', '2004-09-06 18:55:50.000000', NULL, 1),
(896198, 103255, 4871, '<td valign="top">I really like what you''ve done with this photograph - the clouds are perfectly exposed! I would have cropped the bottom into a panoramic pic - esp the light in the middle of the bottom part - very distracting from the overall frame. However that would be my only criticizm - otherwise a perfect picture!</td>', 'I really like what you''ve done with this photograph - the clouds are perfectly exposed! I would have cropped the bottom into a panoramic pic - esp the light in the middle of the bottom part - very distracting from the overall frame. However that would be my only criticizm - otherwise a perfect picture!', '2004-09-06 18:56:36.000000', NULL, 1),
(896201, 102677, 93, '<td valign="top">This is a wonderfully captured moment.  That rainbow is exceedingly bright! :)  I feel this photograph suffers from a slight under-cropping however.  A crop closer to the bottom of the sculpture would be nice to see, as that one stone element in the bottom corner tends to bring the eye from the subject.</td>', 'This is a wonderfully captured moment.  That rainbow is exceedingly bright! :)  I feel this photograph suffers from a slight under-cropping however.  A crop closer to the bottom of the sculpture would be nice to see, as that one stone element in the bottom corner tends to bring the eye from the subject.', '2004-09-06 18:57:16.000000', NULL, 1),
(896202, 103224, 93, '<td valign="top">A very interesting and unique view of the buildings.   A slight rotate to the right would have really helped this I think, as I find myself wanting to tilt my head too much. Nice shot</td>', 'A very interesting and unique view of the buildings.   A slight rotate to the right would have really helped this I think, as I find myself wanting to tilt my head too much. Nice shot', '2004-09-06 18:58:37.000000', NULL, 1),
(896204, 102741, 93, '<td valign="top">I don''t think there''s a better way to say "The Netherlands" at all :) It''s a nice time of day for this shot, I really like how the lights of the windmills start to show here.  I think the focus is just a little soft for my tastes, and a nice bump in contrast might have helped as well?   This is one of the stronger images for the theme that I''ve seen though, so great work!</td>', 'I don''t think there''s a better way to say "The Netherlands" at all :) It''s a nice time of day for this shot, I really like how the lights of the windmills start to show here.  I think the focus is just a little soft for my tastes, and a nice bump in contrast might have helped as well?   This is one of the stronger images for the theme that I''ve seen though, so great work!', '2004-09-06 19:00:48.000000', NULL, 1),
(896207, 102811, 93, '<td valign="top">very reminiscent of shots I''ve seen in a few "getaway" brochures, so well done on that aspect.   I would have liked to have seen the wine bottle, glass, and candle bowl in focus more. It would have given the image a little more weight, and a better strength to lead your eye to the background... which, by the way, is stunning.<br/>it''s a beautifully crafted scene otherwise, so keep it up :)</td>', 'very reminiscent of shots I''ve seen in a few "getaway" brochures, so well done on that aspect.   I would have liked to have seen the wine bottle, glass, and candle bowl in focus more. It would have given the image a little more weight, and a better strength to lead your eye to the background... which, by the way, is stunning.it''s a beautifully crafted scene otherwise, so keep it up :)', '2004-09-06 19:03:36.000000', NULL, 1),
(896209, 101772, 7743, '<td valign="top">The grain in this image gives it a Victorian feel and is very appropriate with your choice of B &amp; W.  Big Ben (I know it''s just the bell but what else do you call it) is a little too central.  Maybe a horizontal shot with more of parliament in the image would work better. 6</td>', 'The grain in this image gives it a Victorian feel and is very appropriate with your choice of B & W.  Big Ben (I know it''s just the bell but what else do you call it) is a little too central.  Maybe a horizontal shot with more of parliament in the image would work better. 6', '2004-09-06 19:06:02.000000', NULL, 1),
(896212, 101801, 10413, '<td valign="top">Love the colors in this.</td>', 'Love the colors in this.', '2004-09-06 19:07:13.000000', NULL, 1),
(896213, 102161, 93, '<td valign="top">I really like this shot except for the soft focus on it, although I realize that the fog probably had something to do with that.  The skyline also looks a little of kilter to me.<br/>I''d also have maybe tried another angle to bring the Trans-America building more into the shot.  It''s cliche to have it as a focal point, I know, but to have it sitting at the edge kind of diminishes the strength of the skyline.. in my opinion.<br/> <br/>It''s an excellent attempt, and I''d love to see more work on the skyline in the future :)</td>', 'I really like this shot except for the soft focus on it, although I realize that the fog probably had something to do with that.  The skyline also looks a little of kilter to me.I''d also have maybe tried another angle to bring the Trans-America building more into the shot.  It''s cliche to have it as a focal point, I know, but to have it sitting at the edge kind of diminishes the strength of the skyline.. in my opinion. It''s an excellent attempt, and I''d love to see more work on the skyline in the future :)', '2004-09-06 19:07:13.000000', NULL, 1),
(896214, 102677, 10413, '<td valign="top">Beautiful rainbow.</td>', 'Beautiful rainbow.', '2004-09-06 19:08:27.000000', NULL, 1),
(896215, 103141, 10413, '<td valign="top">Brilliant sky colors.</td>', 'Brilliant sky colors.', '2004-09-06 19:09:40.000000', NULL, 1),
(896217, 102676, 10413, '<td valign="top">What a neat piece of art.</td>', 'What a neat piece of art.', '2004-09-06 19:10:56.000000', NULL, 1),
(896218, 103074, 16148, '<td valign="top">Beautiful lines and patterns.  Best of the challenge in my opinion.  I might have used a simple white border.  Good luck.</td>', 'Beautiful lines and patterns.  Best of the challenge in my opinion.  I might have used a simple white border.  Good luck.', '2004-09-06 19:11:32.000000', NULL, 1),
(896231, 102416, 10413, '<td valign="top">Breath taking.</td>', 'Breath taking.', '2004-09-06 19:19:52.000000', NULL, 1),
(896233, 103207, 16493, '<td valign="top">laks a bit of sharpnes - maybe camera shake.</td>', 'laks a bit of sharpnes - maybe camera shake.', '2004-09-06 19:20:39.000000', NULL, 1),
(896236, 102248, 16493, '<td valign="top">haha you''ll get here one mile at a time.</td>', 'haha you''ll get here one mile at a time.', '2004-09-06 19:21:26.000000', NULL, 1),
(896237, 102642, 10413, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2004-09-06 19:21:37.000000', NULL, 1),
(896240, 103244, 772, '<td valign="top">best of show... = 10</td>', 'best of show... = 10', '2004-09-06 19:23:12.000000', NULL, 1),
(896253, 102812, 715, '<td valign="top">The scenery is great, the sunbeams are beautifull and I think in total, it''s a very good photo. After looking at the photo af couple of times I still kinda have the feeling that the tree bending towards the center of the image is blocking an important part of the view though.</td>', 'The scenery is great, the sunbeams are beautifull and I think in total, it''s a very good photo. After looking at the photo af couple of times I still kinda have the feeling that the tree bending towards the center of the image is blocking an important part of the view though.', '2004-09-06 19:31:19.000000', NULL, 1),
(896255, 101498, 20066, '<td valign="top">Very simple and I like it a lot !</td>', 'Very simple and I like it a lot !', '2004-09-06 19:32:05.000000', NULL, 1),
(896258, 102350, 10413, '<td valign="top">Would love to see this in person!</td>', 'Would love to see this in person!', '2004-09-06 19:32:47.000000', NULL, 1),
(896268, 102638, 10413, '<td valign="top">How creative these sculptures are. Make me want to see it in person.</td>', 'How creative these sculptures are. Make me want to see it in person.', '2004-09-06 19:37:58.000000', NULL, 1),
(896273, 102666, 25464, '<td valign="top">I didn''t even think about the Zoo.  Good job.</td>', 'I didn''t even think about the Zoo.  Good job.', '2004-09-06 19:40:39.000000', NULL, 1),
(896281, 102785, 25464, '<td valign="top">I have no idea what this is or what it has to do with travel.  Clear, in focus, and backlit.</td>', 'I have no idea what this is or what it has to do with travel.  Clear, in focus, and backlit.', '2004-09-06 19:44:28.000000', NULL, 1),
(896288, 102435, 25464, '<td valign="top">?</td>', '?', '2004-09-06 19:47:21.000000', NULL, 1),
(896292, 101772, 25464, '<td valign="top">I am a fan of black and white, but I think this would have been better in color, at least in this context.   A bit too much grain.</td>', 'I am a fan of black and white, but I think this would have been better in color, at least in this context.   A bit too much grain.', '2004-09-06 19:51:26.000000', NULL, 1),
(896293, 102350, 8533, '<td valign="top">Brilliant lighting</td>', 'Brilliant lighting', '2004-09-06 19:52:19.000000', NULL, 1),
(896300, 102784, 715, '<td valign="top">Besides that it''s a very nice composed and interresting photo, the first thing I noticed was that the top of the windows are not parallel with the top-border of the photo. Because of the alignment of the vertical lines, I can see why you didn''t rotate the photo though.  So, I think you should have made a tighter crop at the top.<br/> <br/>I really do like the link between the old-fashioned looking car outside and the old  people inside the restaurant.</td>', 'Besides that it''s a very nice composed and interresting photo, the first thing I noticed was that the top of the windows are not parallel with the top-border of the photo. Because of the alignment of the vertical lines, I can see why you didn''t rotate the photo though.  So, I think you should have made a tighter crop at the top. I really do like the link between the old-fashioned looking car outside and the old  people inside the restaurant.', '2004-09-06 19:56:49.000000', NULL, 1),
(896301, 103051, 10084, '<td valign="top">Breath taking view from the beach from the incredible blue water to the fluffy white clouds in the sky. The 2 subjects in the photo adds the human factor and makes you feel like you are there with them."10"</td>', 'Breath taking view from the beach from the incredible blue water to the fluffy white clouds in the sky. The 2 subjects in the photo adds the human factor and makes you feel like you are there with them."10"', '2004-09-06 19:57:36.000000', NULL, 1),
(896303, 102546, 23394, '<td valign="top">this is an interesting image, but do not understand why you desaturated it.</td>', 'this is an interesting image, but do not understand why you desaturated it.', '2004-09-06 20:00:15.000000', NULL, 1),
(896304, 102518, 23394, '<td valign="top">this is a beautiful image, however, i think i would like it more if the red lights had been toned down just a hair.</td>', 'this is a beautiful image, however, i think i would like it more if the red lights had been toned down just a hair.', '2004-09-06 20:02:02.000000', NULL, 1),
(896305, 102700, 10084, '<td valign="top">Quite an interesting view. The odd shaped window frames the picture well. The negative space around the frame feels correct. Don''t know if anybody is going to say crop closer, but I feel it''s perfect.<br/> <br/>The view is not the most interesting but you were able to get some good elements in the shot, from the trees to the sky in the background. The house that is almost centered in the shot seems to be the main subject of the shot. "8"</td>', 'Quite an interesting view. The odd shaped window frames the picture well. The negative space around the frame feels correct. Don''t know if anybody is going to say crop closer, but I feel it''s perfect. The view is not the most interesting but you were able to get some good elements in the shot, from the trees to the sky in the background. The house that is almost centered in the shot seems to be the main subject of the shot. "8"', '2004-09-06 20:02:19.000000', NULL, 1),
(896308, 102897, 23394, '<td valign="top">this looks interesting, but i would probably find it more interesting in color...</td>', 'this looks interesting, but i would probably find it more interesting in color...', '2004-09-06 20:02:33.000000', NULL, 1),
(896317, 102666, 10080, '<td valign="top">personally, I just LOVE toucans! And this has great color and detail! The ONLY thing is that I cant see any of the back of his head? But you get an 8 from me anyhow! Send me an original a bit bigger if you could???? I would LOVE to paint this one! emalil me please!</td>', 'personally, I just LOVE toucans! And this has great color and detail! The ONLY thing is that I cant see any of the back of his head? But you get an 8 from me anyhow! Send me an original a bit bigger if you could???? I would LOVE to paint this one! emalil me please!', '2004-09-06 20:17:24.000000', NULL, 1),
(896340, 103051, 16493, '<td valign="top">ahh, if only those people where just walking not bending like that.</td>', 'ahh, if only those people where just walking not bending like that.', '2004-09-06 20:45:54.000000', NULL, 1),
(896350, 103255, 16046, '<td valign="top">Great exposure, love the light on the lighthouse, well done</td>', 'Great exposure, love the light on the lighthouse, well done', '2004-09-06 21:01:56.000000', NULL, 1),
(896353, 101995, 16046, '<td valign="top">Awesome composition, great light, even caught the moon, 10</td>', 'Awesome composition, great light, even caught the moon, 10', '2004-09-06 21:02:57.000000', NULL, 1),
(896355, 102350, 16046, '<td valign="top">This is such a cool image, so much detail, lovely lighting, awesome reflection. The exposure is just right. 10</td>', 'This is such a cool image, so much detail, lovely lighting, awesome reflection. The exposure is just right. 10', '2004-09-06 21:04:56.000000', NULL, 1),
(896357, 102999, 16493, '<td valign="top">?travel guide or don''t travel guide?</td>', '?travel guide or don''t travel guide?', '2004-09-06 21:06:05.000000', NULL, 1),
(896361, 101498, 1827, '<td valign="top">The title is perfect.  Very nicely done.  Reminds me a bit of Remie''s Cowspace.</td>', 'The title is perfect.  Very nicely done.  Reminds me a bit of Remie''s Cowspace.', '2004-09-06 21:10:00.000000', NULL, 1),
(896388, 103052, 17547, '<td valign="top">I was just there this weekend, wanted to take this same shot but it was to hazy and did not work. But you really hit it here, great shot =8</td>', 'I was just there this weekend, wanted to take this same shot but it was to hazy and did not work. But you really hit it here, great shot =8', '2004-09-06 21:27:10.000000', NULL, 1),
(896389, 102973, 17547, '<td valign="top">love the colors, great work. =8</td>', 'love the colors, great work. =8', '2004-09-06 21:27:59.000000', NULL, 1),
(896390, 101658, 17547, '<td valign="top">sure winner, nice and clear with great color and depth.</td>', 'sure winner, nice and clear with great color and depth.', '2004-09-06 21:28:22.000000', NULL, 1),
(896394, 103141, 6999, '<td valign="top">Your subject seems rather relegated in importance in this shot by that sunset. I know many folks are interpreting this challenge more as ''travel brochure'' than guide, but I can''t see this being even effective advertising for the location. Perhaps, as a subversive ironic entry it has some merit, but more in the point you''re making than the score I''m afraid.</td>', 'Your subject seems rather relegated in importance in this shot by that sunset. I know many folks are interpreting this challenge more as ''travel brochure'' than guide, but I can''t see this being even effective advertising for the location. Perhaps, as a subversive ironic entry it has some merit, but more in the point you''re making than the score I''m afraid.', '2004-09-06 21:30:02.000000', NULL, 1),
(896398, 102784, 6999, '<td valign="top">Aligning just one side of the window givves the image a weird falling-over feel. A little distortion correction would have fixed that, and it would be worth fixing i think because otherwise I like the shot: good tonality, sense of compositional balance, although I do wish those characters were better framed by the window. Even like the crop on the car - enough of it to know it, and not slvishly including it siply because it''s a thing. But that slight sense of giddiness from the curvature undermines the image a little all the time.</td>', 'Aligning just one side of the window givves the image a weird falling-over feel. A little distortion correction would have fixed that, and it would be worth fixing i think because otherwise I like the shot: good tonality, sense of compositional balance, although I do wish those characters were better framed by the window. Even like the crop on the car - enough of it to know it, and not slvishly including it siply because it''s a thing. But that slight sense of giddiness from the curvature undermines the image a little all the time.', '2004-09-06 21:33:11.000000', NULL, 1),
(896399, 102444, 6999, '<td valign="top">Lacking drama in the light - just overall too bright a shot for me. Levels, or curves work to bring the contrast out in the scene more strongly would have made it so much more appealling - and possibly helped with that odd greenish cast in the sky.</td>', 'Lacking drama in the light - just overall too bright a shot for me. Levels, or curves work to bring the contrast out in the scene more strongly would have made it so much more appealling - and possibly helped with that odd greenish cast in the sky.', '2004-09-06 21:34:52.000000', NULL, 1),
(896401, 102161, 6999, '<td valign="top">Could certainly see this in a guide - though I''d perhaps want something a touch more distinctive than a simple skyline - so many sea cities have something similar. Technically, faultless, but not quite specific enough, if you follow me.</td>', 'Could certainly see this in a guide - though I''d perhaps want something a touch more distinctive than a simple skyline - so many sea cities have something similar. Technically, faultless, but not quite specific enough, if you follow me.', '2004-09-06 21:36:49.000000', NULL, 1),
(896403, 102332, 10263, '<td valign="top">I love the colors in this one. I always love fog photos. The dark frame works well. I can''t imagine more than one Coquille. You are in Oregon?</td>', 'I love the colors in this one. I always love fog photos. The dark frame works well. I can''t imagine more than one Coquille. You are in Oregon?', '2004-09-06 21:38:20.000000', NULL, 1),
(896404, 103065, 6999, '<td valign="top">Forbidding. Don''t like the halo-ing effect around the top of the thing - if it''s from burning or selection I''d have found a gentler feathering of it less ''processed''. Good textures lower down, composition fine. Too heavyweight for this challenge? We''ll see what folks think - I suspect they''re looking for stuff more like advertising than documentary.</td>', 'Forbidding. Don''t like the halo-ing effect around the top of the thing - if it''s from burning or selection I''d have found a gentler feathering of it less ''processed''. Good textures lower down, composition fine. Too heavyweight for this challenge? We''ll see what folks think - I suspect they''re looking for stuff more like advertising than documentary.', '2004-09-06 21:39:22.000000', NULL, 1),
(896407, 102982, 6999, '<td valign="top">All that negative space ... photogrphaically intersting to me, certainly, but ... I think this challenge demands a shot to be more orthodixly interesting. Cries out for something to be happening there, and whilst I rather like the tonality, I don''t think I would publish it if I were putting a guide together.</td>', 'All that negative space ... photogrphaically intersting to me, certainly, but ... I think this challenge demands a shot to be more orthodixly interesting. Cries out for something to be happening there, and whilst I rather like the tonality, I don''t think I would publish it if I were putting a guide together.', '2004-09-06 21:41:28.000000', NULL, 1),
(896408, 102774, 6999, '<td valign="top">Very very nearly ... but that foreground-most section of wall is just too intrusive, without really adding much in drama or visual interest for me. Shot from that touch closer, using the steel rrail as your leading line, I could see this scoring fabulously well. Great exposure, details, light, subject.</td>', 'Very very nearly ... but that foreground-most section of wall is just too intrusive, without really adding much in drama or visual interest for me. Shot from that touch closer, using the steel rrail as your leading line, I could see this scoring fabulously well. Great exposure, details, light, subject.', '2004-09-06 21:44:10.000000', NULL, 1),
(896410, 102267, 6999, '<td valign="top">Slight wide-angle effect is a touch disorienting for me - has that falling over backwards feeling, a bit off-putting in this challenge. Technically accomplished otherwise, compositionally just a touch heavy in the centre without enough weight of interest to off-set that.</td>', 'Slight wide-angle effect is a touch disorienting for me - has that falling over backwards feeling, a bit off-putting in this challenge. Technically accomplished otherwise, compositionally just a touch heavy in the centre without enough weight of interest to off-set that.', '2004-09-06 21:46:10.000000', NULL, 1),
(896411, 103163, 10263, '<td valign="top">Breath taking. The colors are wonderful. The composition is great. This one has to ribbon. 10</td>', 'Breath taking. The colors are wonderful. The composition is great. This one has to ribbon. 10', '2004-09-06 21:46:55.000000', NULL, 1),
(896412, 102295, 25150, '<td valign="top">I like it, but it just doesn''t look like a photo anymore.</td>', 'I like it, but it just doesn''t look like a photo anymore.', '2004-09-06 21:47:48.000000', NULL, 1),
(896413, 103193, 6999, '<td valign="top">Don''t know about those dark halos - but intrigued to know what they''re an artefact of. Wonderful scene, and those odd things are the more of a shame for it. It''d be a pretty off-the-wall guide to publish this, no? A good clean version would be a pretty sure near winner, I''d think. Like this ...</td>', 'Don''t know about those dark halos - but intrigued to know what they''re an artefact of. Wonderful scene, and those odd things are the more of a shame for it. It''d be a pretty off-the-wall guide to publish this, no? A good clean version would be a pretty sure near winner, I''d think. Like this ...', '2004-09-06 21:48:14.000000', NULL, 1),
(896421, 103084, 6999, '<td valign="top">Much more to the point than the black-and-white one ... I''m wondering how many more shos of it there are going to be. For the challenge, pretty good I''d say although the perspective distortion might have been lessened a touch. Great light, perhaps only a touch too subtle for a travel guide. Pretty close though.</td>', 'Much more to the point than the black-and-white one ... I''m wondering how many more shos of it there are going to be. For the challenge, pretty good I''d say although the perspective distortion might have been lessened a touch. Great light, perhaps only a touch too subtle for a travel guide. Pretty close though.', '2004-09-06 21:53:06.000000', NULL, 1),
(896422, 103242, 10263, '<td valign="top">Wow, this looks like a painting. I love the muted colors. In fact I love everything about it. 10</td>', 'Wow, this looks like a painting. I love the muted colors. In fact I love everything about it. 10', '2004-09-06 21:53:16.000000', NULL, 1),
(896426, 103054, 6999, '<td valign="top">What have you done to the sky? Burnt out and so put in a colour? That''s how it looks - terribly flat. Good composition though, and pretty good exposure. I''d have tried a graduated fill on that sky, to give some sense of the real, but it''s nevertheless a very tricky thing to achieve, so that failure perhaps souldn''t cost too dearly.</td>', 'What have you done to the sky? Burnt out and so put in a colour? That''s how it looks - terribly flat. Good composition though, and pretty good exposure. I''d have tried a graduated fill on that sky, to give some sense of the real, but it''s nevertheless a very tricky thing to achieve, so that failure perhaps souldn''t cost too dearly.', '2004-09-06 21:55:24.000000', NULL, 1),
(896427, 103238, 18191, '<td valign="top">I think that this is an interesting composition, but it does not seem to be a photo that I would find myself seeing in a magazine. Besides that, the light coming from the top of the stairs looks a little bit blown out.</td>', 'I think that this is an interesting composition, but it does not seem to be a photo that I would find myself seeing in a magazine. Besides that, the light coming from the top of the stairs looks a little bit blown out.', '2004-09-06 21:55:26.000000', NULL, 1),
(896429, 102447, 10263, '<td valign="top">Outstanding. The colors are wonderful. This one should ribbon. 10</td>', 'Outstanding. The colors are wonderful. This one should ribbon. 10', '2004-09-06 21:55:57.000000', NULL, 1),
