(896454, 102677, 16046, '<td valign="top">Cool sculpture, very nice capture of that rainbow, stong color, well done</td>', 'Cool sculpture, very nice capture of that rainbow, stong color, well done', '2004-09-06 22:09:20.000000', NULL, 1),
(896456, 103086, 9690, '<td valign="top">Beautiful.  Im a sucker for stadium shots.  Theres a certain grandeur that you have captured well.  Great job</td>', 'Beautiful.  Im a sucker for stadium shots.  Theres a certain grandeur that you have captured well.  Great job', '2004-09-06 22:09:58.000000', NULL, 1),
