(896464, 102161, 16046, '<td valign="top">excellent night shot, would like to see some water reflecting light, well done</td>', 'excellent night shot, would like to see some water reflecting light, well done', '2004-09-06 22:12:16.000000', NULL, 1),
(896466, 102422, 11738, '<td valign="top">Man, texaz Longhorns are scary lookin''.  Too bad you couldn''t get closer to get more cows and cowboys and less surroundings.</td>', 'Man, texaz Longhorns are scary lookin''.  Too bad you couldn''t get closer to get more cows and cowboys and less surroundings.', '2004-09-06 22:12:55.000000', NULL, 1),
