(898223, 102642, 16301, '<td valign="top">Very beautiful! I love the colors. Nice composition too...(9)</td>', 'Very beautiful! I love the colors. Nice composition too...(9)', '2004-09-07 22:53:17.000000', NULL, 1),
(898228, 103238, 16301, '<td valign="top">Somehow I feel that this is getting a beating for being outside the box. But hey, I like it (8)...</td>', 'Somehow I feel that this is getting a beating for being outside the box. But hey, I like it (8)...', '2004-09-07 22:55:34.000000', NULL, 1),
(898243, 102296, 16301, '<td valign="top">I think this would have looked better with some dramatic sunlight to brighten up the landscape and make it more interesting to the viewer.<br/> <br/>On a sidenote, "breath" is a noun and "breathe" is a verb...<br/> <br/>Good luck (6)</td>', 'I think this would have looked better with some dramatic sunlight to brighten up the landscape and make it more interesting to the viewer. On a sidenote, "breath" is a noun and "breathe" is a verb... Good luck (6)', '2004-09-07 23:05:29.000000', NULL, 1),
(898249, 103155, 16301, '<td valign="top">Lovely composition, great job! One of my favs in the challenge (10)</td>', 'Lovely composition, great job! One of my favs in the challenge (10)', '2004-09-07 23:08:07.000000', NULL, 1),
(898256, 103166, 16301, '<td valign="top">The blues and cyans are just too much for the eye to handle, desaturating them a little would have helped...</td>', 'The blues and cyans are just too much for the eye to handle, desaturating them a little would have helped...', '2004-09-07 23:14:08.000000', NULL, 1),
(898264, 103255, 16301, '<td valign="top">Just WOW! Amazing scene you''ve captured here. I love how the lighthouse is lighted. Definitely a 10. +fav<br/> <br/>Two things I would have did here:<br/>1- Clonning out the person.<br/>2- Clonning out the puddle of water in the bottom of the frame.<br/> <br/>Good luck...</td>', 'Just WOW! Amazing scene you''ve captured here. I love how the lighthouse is lighted. Definitely a 10. +fav Two things I would have did here:1- Clonning out the person.2- Clonning out the puddle of water in the bottom of the frame. Good luck...', '2004-09-07 23:24:35.000000', NULL, 1),
(898265, 103160, 10080, '<td valign="top">What a GREAT shot! The only one that had a WOW factor for me so far! I would hope that ya get a ribbon! Congrats ahead of time, and if not, you got one from me!</td>', 'What a GREAT shot! The only one that had a WOW factor for me so far! I would hope that ya get a ribbon! Congrats ahead of time, and if not, you got one from me!', '2004-09-07 23:26:13.000000', NULL, 1),
(898266, 103141, 16301, '<td valign="top">Very nice, I like the colors and reflection. (9)</td>', 'Very nice, I like the colors and reflection. (9)', '2004-09-07 23:26:49.000000', NULL, 1),
(898269, 102811, 18799, '<td valign="top">I like the concept, but the foreground lighting is too strong and makes the picture unnatural looking.  I find the shirt to be a distraction too.  Maybe grouping the objects tighter and cropping tighter would help.</td>', 'I like the concept, but the foreground lighting is too strong and makes the picture unnatural looking.  I find the shirt to be a distraction too.  Maybe grouping the objects tighter and cropping tighter would help.', '2004-09-07 23:27:57.000000', NULL, 1),
(898270, 103122, 16301, '<td valign="top">Very beautiful, I love the composition. (9)</td>', 'Very beautiful, I love the composition. (9)', '2004-09-07 23:28:14.000000', NULL, 1),
(898273, 102808, 18799, '<td valign="top">This just doesn''t make me want to visit, sorry</td>', 'This just doesn''t make me want to visit, sorry', '2004-09-07 23:29:02.000000', NULL, 1),
(898276, 103064, 18799, '<td valign="top">I don''t get it</td>', 'I don''t get it', '2004-09-07 23:29:45.000000', NULL, 1),
(898277, 103154, 16301, '<td valign="top">Awesome! I love the silhouettes and composition. (9)</td>', 'Awesome! I love the silhouettes and composition. (9)', '2004-09-07 23:29:52.000000', NULL, 1),
(898279, 102123, 16301, '<td valign="top">Beautiful! I love the leading lines. (9)</td>', 'Beautiful! I love the leading lines. (9)', '2004-09-07 23:31:30.000000', NULL, 1),
(898281, 102007, 10080, '<td valign="top">Gorgeous shot! I love the colors and the contrast, I just am a bit thrown off by the heavy burnt in sky! Still a 7 from me, and good work!</td>', 'Gorgeous shot! I love the colors and the contrast, I just am a bit thrown off by the heavy burnt in sky! Still a 7 from me, and good work!', '2004-09-07 23:33:32.000000', NULL, 1),
