INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(898286, 102784, 18799, '<td valign="top">This photo just doesn''t make me want to visit, or turn the page in the brochure.  The car is cropped awkwardly, the colors are flat, the man at the table has only half a face and the subject is too much in the center of the picture.  It looks very much like a quick snapshot without a lot of thought or planning.  <br/>No offense, not trying to be mean spirited.</td>', 'This photo just doesn''t make me want to visit, or turn the page in the brochure.  The car is cropped awkwardly, the colors are flat, the man at the table has only half a face and the subject is too much in the center of the picture.  It looks very much like a quick snapshot without a lot of thought or planning.  No offense, not trying to be mean spirited.', '2004-09-07 23:35:42.000000', NULL, 1),
(898288, 102812, 16301, '<td valign="top">Amazing light you''ve captured here...(9)</td>', 'Amazing light you''ve captured here...(9)', '2004-09-07 23:36:05.000000', NULL, 1),
(898290, 103122, 10080, '<td valign="top">I am sure that you have gotton a ton of bitching over your border choice, but I think that the image itself is beautiful! The border itself doesn''t bug me, but you would have rated MUCH better without one. I have just learned from the same thing.</td>', 'I am sure that you have gotton a ton of bitching over your border choice, but I think that the image itself is beautiful! The border itself doesn''t bug me, but you would have rated MUCH better without one. I have just learned from the same thing.', '2004-09-07 23:36:55.000000', NULL, 1),
(898293, 101995, 16301, '<td valign="top">I love how the church is lighted. Great colors and composition too. (9)</td>', 'I love how the church is lighted. Great colors and composition too. (9)', '2004-09-07 23:37:18.000000', NULL, 1),
(898300, 103211, 18799, '<td valign="top">This photo is too flat and contrasty for me.  There is are a lot of blown highlights and the focus is not great.  It looks as if you took this picture in the middle of the day - a difficult time for even the best photographers to shoot.</td>', 'This photo is too flat and contrasty for me.  There is are a lot of blown highlights and the focus is not great.  It looks as if you took this picture in the middle of the day - a difficult time for even the best photographers to shoot.', '2004-09-07 23:38:46.000000', NULL, 1),
(898305, 102295, 16301, '<td valign="top">Sorry, but i''m supposed to vote on photos, I think this is way too processed.</td>', 'Sorry, but i''m supposed to vote on photos, I think this is way too processed.', '2004-09-07 23:42:38.000000', NULL, 1),
(898313, 103121, 18799, '<td valign="top">It''s a nice enought photograph, but nothing that would make me want to visit.</td>', 'It''s a nice enought photograph, but nothing that would make me want to visit.', '2004-09-07 23:45:56.000000', NULL, 1),
(898320, 103073, 18799, '<td valign="top">This image is quite flat to me.  The land and trees are dark and the water is dull.  The people have halos around them too.  My guess is that the resolution of the camera is not quite capable of a shot like this that has fine details in it.</td>', 'This image is quite flat to me.  The land and trees are dark and the water is dull.  The people have halos around them too.  My guess is that the resolution of the camera is not quite capable of a shot like this that has fine details in it.', '2004-09-07 23:48:38.000000', NULL, 1),
(898323, 102539, 18799, '<td valign="top">The tree in front of the building and it''s shadow really detract from this otherwise neat building</td>', 'The tree in front of the building and it''s shadow really detract from this otherwise neat building', '2004-09-07 23:49:55.000000', NULL, 1),
(898426, 102676, 26568, '<td valign="top">Absolutely beautiful</td>', 'Absolutely beautiful', '2004-09-08 00:34:34.000000', NULL, 1),
(898432, 102422, 26568, '<td valign="top">That''s something I would love to see.<br/></td>', 'That''s something I would love to see.', '2004-09-08 00:37:06.000000', NULL, 1),
(898434, 102123, 24126, '<td valign="top">LOve the black and white with sepia added.  Great shot.</td>', 'LOve the black and white with sepia added.  Great shot.', '2004-09-08 00:37:30.000000', NULL, 1),
(898560, 103155, 25773, '<td valign="top">A cafe with no people? Is it a museum? The picture is nice but I miss the ''living components''.</td>', 'A cafe with no people? Is it a museum? The picture is nice but I miss the ''living components''.', '2004-09-08 01:15:44.000000', NULL, 1),
(898648, 102738, 8054, '<td valign="top">Nice motion blur of the waterfall but with the slow shutter speed you also sacrificed the ability to focus on the leaves and anything else that may move. As such, I really don''t see anything in sharp focus despite the fact you wanted to blur the waterfall. The leaves look strange, too. Are they really that color?</td>', 'Nice motion blur of the waterfall but with the slow shutter speed you also sacrificed the ability to focus on the leaves and anything else that may move. As such, I really don''t see anything in sharp focus despite the fact you wanted to blur the waterfall. The leaves look strange, too. Are they really that color?', '2004-09-08 01:33:32.000000', NULL, 1),
(898656, 103245, 8054, '<td valign="top">Colors, contrast and focus are all excellent. Composition is where this needs help. This looks too snapshot-like.</td>', 'Colors, contrast and focus are all excellent. Composition is where this needs help. This looks too snapshot-like.', '2004-09-08 01:35:57.000000', NULL, 1),
(898701, 101498, 8054, '<td valign="top">Very impressive cloud formation and as a dominant feature of the photo. It would look more impressive if there was higher contrast in the clouds than is currently offered. The border is also a bit too thick.</td>', 'Very impressive cloud formation and as a dominant feature of the photo. It would look more impressive if there was higher contrast in the clouds than is currently offered. The border is also a bit too thick.', '2004-09-08 01:45:57.000000', NULL, 1),
(898745, 102416, 8054, '<td valign="top">Despite the high contrast, I really like this shot. Love the wispy cirrus clouds and their reflection on the still water. I don''t really care for the dark lower right corner but that''s probably the shoreline/bank and cannot be helped nor cropped out. Looks like there is a slight amount of vignetting but it looks good with the intense contrast as it helps to frame the sky. 10</td>', 'Despite the high contrast, I really like this shot. Love the wispy cirrus clouds and their reflection on the still water. I don''t really care for the dark lower right corner but that''s probably the shoreline/bank and cannot be helped nor cropped out. Looks like there is a slight amount of vignetting but it looks good with the intense contrast as it helps to frame the sky. 10', '2004-09-08 01:59:04.000000', NULL, 1),
(898963, 102973, 5728, '<td valign="top">Windmill shots always do well on postcards and travel guides :)</td>', 'Windmill shots always do well on postcards and travel guides :)', '2004-09-08 03:15:17.000000', NULL, 1),
(898969, 101801, 5728, '<td valign="top">Wow, fantastic!!</td>', 'Wow, fantastic!!', '2004-09-08 03:16:55.000000', NULL, 1),
(898976, 101995, 5728, '<td valign="top">Good use of available light!</td>', 'Good use of available light!', '2004-09-08 03:19:35.000000', NULL, 1),
(898988, 102741, 5728, '<td valign="top">.... and windmills of course :)))))  Good one!</td>', '.... and windmills of course :)))))  Good one!', '2004-09-08 03:24:14.000000', NULL, 1),
(898992, 102246, 5728, '<td valign="top">aKiwi is that you? Choice shot, and a good idea, the Olympic Stadium :)</td>', 'aKiwi is that you? Choice shot, and a good idea, the Olympic Stadium :)', '2004-09-08 03:25:45.000000', NULL, 1),
(898997, 102416, 5728, '<td valign="top">Gorgeous! (10).</td>', 'Gorgeous! (10).', '2004-09-08 03:27:11.000000', NULL, 1),
(899000, 102381, 5728, '<td valign="top">Aha the Algarve!! Good shot, it looks like this place was spared from the extensive forest fires there recently.</td>', 'Aha the Algarve!! Good shot, it looks like this place was spared from the extensive forest fires there recently.', '2004-09-08 03:28:10.000000', NULL, 1),
(899002, 103084, 5728, '<td valign="top">Ah! The second time I see this church in this challenge :) Very good perspective!</td>', 'Ah! The second time I see this church in this challenge :) Very good perspective!', '2004-09-08 03:29:09.000000', NULL, 1),
(899003, 103211, 5728, '<td valign="top">The composition is good, but the image is quite oversharpened in my opinion.</td>', 'The composition is good, but the image is quite oversharpened in my opinion.', '2004-09-08 03:29:41.000000', NULL, 1),
(899007, 102007, 5728, '<td valign="top">One of the best in the challenge! (10)</td>', 'One of the best in the challenge! (10)', '2004-09-08 03:30:36.000000', NULL, 1),
(899019, 103086, 5728, '<td valign="top">Amazing shot, awesome colors, wow!</td>', 'Amazing shot, awesome colors, wow!', '2004-09-08 03:33:42.000000', NULL, 1),
(899034, 102267, 5728, '<td valign="top">Just ogtta love those onion domed churches! Good shot, no blow outs at all on the white paint!</td>', 'Just ogtta love those onion domed churches! Good shot, no blow outs at all on the white paint!', '2004-09-08 03:37:46.000000', NULL, 1),
(899039, 102350, 5728, '<td valign="top">Fantastic shot, good composition and lighting. The reflection in the water is stunning. I am not sure the border does this image justice though. (8)</td>', 'Fantastic shot, good composition and lighting. The reflection in the water is stunning. I am not sure the border does this image justice though. (8)', '2004-09-08 03:39:52.000000', NULL, 1),
(899067, 103064, 8054, '<td valign="top">I really like this as it has a stock photography feel to it. The "break-the-rules" cropping style also sets this photo apart from the rest. Excellent work! 10</td>', 'I really like this as it has a stock photography feel to it. The "break-the-rules" cropping style also sets this photo apart from the rest. Excellent work! 10', '2004-09-08 03:55:39.000000', NULL, 1),
(899147, 103064, 19959, '<td valign="top">Unusual take on the challenge. Great photo.</td>', 'Unusual take on the challenge. Great photo.', '2004-09-08 04:31:29.000000', NULL, 1),
(899152, 102892, 19959, '<td valign="top">I''ve never seen an ''artistic'' approach like this is a travel guide. Sorry, this doesn''t work for me. The bland sky does not help the shot either.</td>', 'I''ve never seen an ''artistic'' approach like this is a travel guide. Sorry, this doesn''t work for me. The bland sky does not help the shot either.', '2004-09-08 04:33:04.000000', NULL, 1),
(899154, 103073, 19959, '<td valign="top">Sorry, this shot does not work for me. The sky is great but you have lost detail in the land. A graduated ND filter can help ''balance'' the picture.</td>', 'Sorry, this shot does not work for me. The sky is great but you have lost detail in the land. A graduated ND filter can help ''balance'' the picture.', '2004-09-08 04:34:05.000000', NULL, 1),
(899170, 102999, 19959, '<td valign="top">Interesting idea... not sure that this would be a good travel guide picture. I like it though.</td>', 'Interesting idea... not sure that this would be a good travel guide picture. I like it though.', '2004-09-08 04:39:18.000000', NULL, 1),
(899175, 103241, 19959, '<td valign="top">Nice picture with goo composition. It seems to lack ''punch'' though.  Maybe tweaking the levels would help?</td>', 'Nice picture with goo composition. It seems to lack ''punch'' though.  Maybe tweaking the levels would help?', '2004-09-08 04:40:55.000000', NULL, 1),
(899179, 102897, 19959, '<td valign="top">might have worked better in color...</td>', 'might have worked better in color...', '2004-09-08 04:42:14.000000', NULL, 1),
(899181, 102117, 19959, '<td valign="top">Excellent.</td>', 'Excellent.', '2004-09-08 04:42:27.000000', NULL, 1),
(899219, 103266, 19959, '<td valign="top">Excellent. Maybe a tighter crop lose some of the water and some of the sky.</td>', 'Excellent. Maybe a tighter crop lose some of the water and some of the sky.', '2004-09-08 04:55:56.000000', NULL, 1),
(899426, 103053, 19982, '<td valign="top">Love the colors and the textures in the water and beach.  Great shot.  Good luck in the challenge.</td>', 'Love the colors and the textures in the water and beach.  Great shot.  Good luck in the challenge.', '2004-09-08 07:39:22.000000', NULL, 1),
(899429, 102653, 19982, '<td valign="top">I like the framing...  but for me the overall tone of the picture is just too dark and "uninviting".  In Travel Guides I would expect the photos would make you want to visit the place, and a dark photo will tend not to do that.  For a different challenge (such as framing) this photo would probably have done better.</td>', 'I like the framing...  but for me the overall tone of the picture is just too dark and "uninviting".  In Travel Guides I would expect the photos would make you want to visit the place, and a dark photo will tend not to do that.  For a different challenge (such as framing) this photo would probably have done better.', '2004-09-08 07:42:09.000000', NULL, 1),
(899435, 102518, 21500, '<td valign="top">good job, holmes!</td>', 'good job, holmes!', '2004-09-08 07:45:24.000000', NULL, 1),
(899437, 102812, 21500, '<td valign="top">cool</td>', 'cool', '2004-09-08 07:46:03.000000', NULL, 1),
(899441, 102117, 21500, '<td valign="top">very cool.  think I might have liked it better with different composition - maybe no birds and different angle - but very cool pic!</td>', 'very cool.  think I might have liked it better with different composition - maybe no birds and different angle - but very cool pic!', '2004-09-08 07:52:27.000000', NULL, 1),
(899442, 103141, 21500, '<td valign="top">that''s a nice picture - I like the color transition in the sky - would have been cool to get it in the reflection too!</td>', 'that''s a nice picture - I like the color transition in the sky - would have been cool to get it in the reflection too!', '2004-09-08 07:53:05.000000', NULL, 1),
