(899455, 102952, 26518, '<td valign="top">Excellent use of natural color!  Nice work.</td>', 'Excellent use of natural color!  Nice work.', '2004-09-08 08:03:43.000000', NULL, 1),
(899456, 103154, 26518, '<td valign="top">Interesting.</td>', 'Interesting.', '2004-09-08 08:04:45.000000', NULL, 1),
(899462, 102973, 26518, '<td valign="top">Nice shot, makes you feel like you are there.</td>', 'Nice shot, makes you feel like you are there.', '2004-09-08 08:08:01.000000', NULL, 1),
(899463, 102816, 26518, '<td valign="top">Nice blend of the old and new.</td>', 'Nice blend of the old and new.', '2004-09-08 08:08:56.000000', NULL, 1),
