(899483, 102653, 26518, '<td valign="top">Nice sunset, has some interest to it!</td>', 'Nice sunset, has some interest to it!', '2004-09-08 08:22:20.000000', NULL, 1),
(899484, 102987, 26518, '<td valign="top">Photo looks like it would be really good but it is blurry.  Maybe the download.</td>', 'Photo looks like it would be really good but it is blurry.  Maybe the download.', '2004-09-08 08:23:04.000000', NULL, 1),
(899486, 102677, 26518, '<td valign="top">Good catch!</td>', 'Good catch!', '2004-09-08 08:25:42.000000', NULL, 1),
