(903293, 102797, 24454, '<td valign="top">Great picture!  I want to go there!</td>', 'Great picture!  I want to go there!', '2004-09-10 12:01:16.000000', NULL, 1),
(903295, 103220, 24454, '<td valign="top">How pretty and striking!  This is my first 10 ofthe challenge!  It''s perfect.</td>', 'How pretty and striking!  This is my first 10 ofthe challenge!  It''s perfect.', '2004-09-10 12:02:26.000000', NULL, 1),
(903304, 103011, 24454, '<td valign="top">Very impressive.  I know how hard rainbows are to get in a shot.</td>', 'Very impressive.  I know how hard rainbows are to get in a shot.', '2004-09-10 12:07:21.000000', NULL, 1),
(903306, 102677, 24454, '<td valign="top">This is so pretty.  I''m especially impressed because I know how hard it is to capture a rainbow in a picture.</td>', 'This is so pretty.  I''m especially impressed because I know how hard it is to capture a rainbow in a picture.', '2004-09-10 12:08:28.000000', NULL, 1),
(903310, 102405, 24454, '<td valign="top">This is a perfect travel guide picture!</td>', 'This is a perfect travel guide picture!', '2004-09-10 12:12:02.000000', NULL, 1),
(903314, 102812, 24454, '<td valign="top">Oooooh.  This is beautiful!  When I first saw the title "Scenic Oklahoma", I thought, "Naah.  I''ve been to Southwest Oklahoma, and it''s not very scenic", but you have really pulled it off!   And imo THAT is what makes a great photographer!</td>', 'Oooooh.  This is beautiful!  When I first saw the title "Scenic Oklahoma", I thought, "Naah.  I''ve been to Southwest Oklahoma, and it''s not very scenic", but you have really pulled it off!   And imo THAT is what makes a great photographer!', '2004-09-10 12:14:41.000000', NULL, 1),
(903318, 102638, 24454, '<td valign="top">This is a perfect picture!  Incredible depth of field to have everything so clear in both the foreground and the city so far away!  Easy 10.</td>', 'This is a perfect picture!  Incredible depth of field to have everything so clear in both the foreground and the city so far away!  Easy 10.', '2004-09-10 12:15:52.000000', NULL, 1),
(903320, 102161, 24454, '<td valign="top">Very cool!  I could really see this one framed on a wall!</td>', 'Very cool!  I could really see this one framed on a wall!', '2004-09-10 12:16:40.000000', NULL, 1),
