(903361, 103238, 8367, '<td valign="top">Good one! Great photo.</td>', 'Good one! Great photo.', '2004-09-10 12:47:33.000000', NULL, 1),
(903364, 102322, 24454, '<td valign="top">Very nice picture.  Great depth of field.  Everything is nice and cear from top to bottom &amp; front to back.  You captured the lighting very well!</td>', 'Very nice picture.  Great depth of field.  Everything is nice and cear from top to bottom & front to back.  You captured the lighting very well!', '2004-09-10 12:49:18.000000', NULL, 1),
(903375, 102987, 24454, '<td valign="top">Wow!  I really like this picture.   I''m not a big fan of the west -- but you have really pulled off making it look inviting  :)</td>', 'Wow!  I really like this picture.   I''m not a big fan of the west -- but you have really pulled off making it look inviting  :)', '2004-09-10 13:02:30.000000', NULL, 1),
