(903543, 103255, 24925, '<td valign="top">Ah yes, the typical shot that I would find in a typical East Canadian Coast travel guide.<br/> <br/>This is very well done.  The sunrise balances the lighthouse nicely.  Unless it''s a sunset on the west coast, I guess!<br/> <br/></td>', 'Ah yes, the typical shot that I would find in a typical East Canadian Coast travel guide. This is very well done.  The sunrise balances the lighthouse nicely.  Unless it''s a sunset on the west coast, I guess! ', '2004-09-10 15:07:58.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(903544, 103162, 24925, '<td valign="top">What''s on those trees?  The top of this picture is cropped in a rather strange spot (just shy of the top of this building), but other than that (and the tree mystery) I like this shot and could picture it in a travel guide.</td>', 'What''s on those trees?  The top of this picture is cropped in a rather strange spot (just shy of the top of this building), but other than that (and the tree mystery) I like this shot and could picture it in a travel guide.', '2004-09-10 15:10:10.000000', NULL, 1),
(903545, 101658, 24925, '<td valign="top">Excellent picture and you know why.  Very smart background, showing the best of both worlds...</td>', 'Excellent picture and you know why.  Very smart background, showing the best of both worlds...', '2004-09-10 15:11:38.000000', NULL, 1),
(903549, 103042, 24925, '<td valign="top">Crazy.  It''s neat to see so many balloons in the same area but the bright colours we''re used to seeing on these balloons are conspicuously absent from the photograph.</td>', 'Crazy.  It''s neat to see so many balloons in the same area but the bright colours we''re used to seeing on these balloons are conspicuously absent from the photograph.', '2004-09-10 15:14:10.000000', NULL, 1),
(903551, 102999, 24925, '<td valign="top">One more comment for the "I''m not sure if I would ever see this in a travel guide!" section...</td>', 'One more comment for the "I''m not sure if I would ever see this in a travel guide!" section...', '2004-09-10 15:15:00.000000', NULL, 1),
(903605, 101818, 8139, '<td valign="top">Something else....good...</td>', 'Something else....good...', '2004-09-10 16:01:31.000000', NULL, 1),
(903610, 102985, 8139, '<td valign="top">Very nice POV. Surnatural colors. A good one :)</td>', 'Very nice POV. Surnatural colors. A good one :)', '2004-09-10 16:03:03.000000', NULL, 1),
(903619, 103155, 8139, '<td valign="top">Some people in the cafe could give more life on this otherwise good photo.</td>', 'Some people in the cafe could give more life on this otherwise good photo.', '2004-09-10 16:07:30.000000', NULL, 1),
(903622, 102432, 8139, '<td valign="top">Remembers me a bridge in Amsterdam. Cool.</td>', 'Remembers me a bridge in Amsterdam. Cool.', '2004-09-10 16:08:51.000000', NULL, 1),
(903628, 101498, 8139, '<td valign="top">absolutly awesome....superb composition. 10</td>', 'absolutly awesome....superb composition. 10', '2004-09-10 16:12:05.000000', NULL, 1),
(903633, 103209, 8139, '<td valign="top">Interesting photography, nice compo , but don''t see this in a travel guide. (well, a conventional guide I mean :) . good effort anyway.</td>', 'Interesting photography, nice compo , but don''t see this in a travel guide. (well, a conventional guide I mean :) . good effort anyway.', '2004-09-10 16:15:23.000000', NULL, 1),
(903635, 102332, 6999, '<td valign="top">This is wonderful. A monumentally well controlled and processed shot. Love the tones particularly, in the grasses, and the progression of light in the mist. Not quite sure it really fits - it isn''t the kind of big bright shot i''d expect to see in a guide. Want to give it a ten, but that consideration is just going to cost you a point.</td>', 'This is wonderful. A monumentally well controlled and processed shot. Love the tones particularly, in the grasses, and the progression of light in the mist. Not quite sure it really fits - it isn''t the kind of big bright shot i''d expect to see in a guide. Want to give it a ten, but that consideration is just going to cost you a point.', '2004-09-10 16:16:05.000000', NULL, 1),
(903636, 101801, 8139, '<td valign="top">Good compo and saturated colors.</td>', 'Good compo and saturated colors.', '2004-09-10 16:16:46.000000', NULL, 1),
(903639, 102296, 6999, '<td valign="top">Would really like to see more definition worked into the hills and the trees; for me, this is too close to being a sky shot rather than a place shot. It would have been a fairly easy trick in post, too. Good shot though, but I don''t quite think it nails the challenge enough. 7</td>', 'Would really like to see more definition worked into the hills and the trees; for me, this is too close to being a sky shot rather than a place shot. It would have been a fairly easy trick in post, too. Good shot though, but I don''t quite think it nails the challenge enough. 7', '2004-09-10 16:18:40.000000', NULL, 1),
(903643, 103237, 6999, '<td valign="top">Beautiful work - exceptional detail, control, mood. To get into a travel guide I would have expected a flora shot to have an exceptional quality, something in the use of detail to give an impression of a wider, larger, state, andi think this has it; it suggests, largely by the darkness of background, a tree-shaded water garden. Top shot.</td>', 'Beautiful work - exceptional detail, control, mood. To get into a travel guide I would have expected a flora shot to have an exceptional quality, something in the use of detail to give an impression of a wider, larger, state, andi think this has it; it suggests, largely by the darkness of background, a tree-shaded water garden. Top shot.', '2004-09-10 16:20:44.000000', NULL, 1),
(903649, 102642, 6999, '<td valign="top">Don''t know if it''s the glass f wine I''m in the middle of, or whether there''s something slightly odd about this shot. The perspective distortion seems a little strong, and maybe the black point is a touch bright: I like the smoothness of tone that gives, but at the same time I miss the contrast. A touch more shadow might have removed some of the two-dimensional feeling from the image. Can absolutely see it in print, though.</td>', 'Don''t know if it''s the glass f wine I''m in the middle of, or whether there''s something slightly odd about this shot. The perspective distortion seems a little strong, and maybe the black point is a touch bright: I like the smoothness of tone that gives, but at the same time I miss the contrast. A touch more shadow might have removed some of the two-dimensional feeling from the image. Can absolutely see it in print, though.', '2004-09-10 16:23:35.000000', NULL, 1),
(903655, 103063, 6999, '<td valign="top">I thought for a moment this was going to be Hallsgrimkirka (or whatever it''s called) again. I like it as a photograph, I''m not sure about it for a travel guide: the framing is a bit odd losing the tower like that. The modernist fluting of those pillars is surely worth concentrating on, but I think you''ve tried to include too much else with it.</td>', 'I thought for a moment this was going to be Hallsgrimkirka (or whatever it''s called) again. I like it as a photograph, I''m not sure about it for a travel guide: the framing is a bit odd losing the tower like that. The modernist fluting of those pillars is surely worth concentrating on, but I think you''ve tried to include too much else with it.', '2004-09-10 16:26:32.000000', NULL, 1),
(903658, 103162, 6999, '<td valign="top">When you select areas to brighten, like tthe shadowed edge of those flowers, two things are really useful: firstly, use increased contrast to hide some of the effect, so that black areas don''t become grey, and also the ''feather'' control, which fades the edge of the selection and makes it much less of a hard line like that. It lets down what was otherwise a very fine shot, I think - ideal for the challenge.</td>', 'When you select areas to brighten, like tthe shadowed edge of those flowers, two things are really useful: firstly, use increased contrast to hide some of the effect, so that black areas don''t become grey, and also the ''feather'' control, which fades the edge of the selection and makes it much less of a hard line like that. It lets down what was otherwise a very fine shot, I think - ideal for the challenge.', '2004-09-10 16:28:42.000000', NULL, 1),
(903660, 103224, 6999, '<td valign="top">Tempted to put simply ''correct'' here :-) Absolutely the right use of a detail shot to convey a wider impression. The severe brightness of the central building''s windows might have been controlled a litttle better, I think, it just verges too close to burn-out to my eye. Otherwise, a fine shot.</td>', 'Tempted to put simply ''correct'' here :-) Absolutely the right use of a detail shot to convey a wider impression. The severe brightness of the central building''s windows might have been controlled a litttle better, I think, it just verges too close to burn-out to my eye. Otherwise, a fine shot.', '2004-09-10 16:30:57.000000', NULL, 1),
(903670, 103102, 10670, '<td valign="top">great photo I love it! The Composition and color are perfect.</td>', 'great photo I love it! The Composition and color are perfect.', '2004-09-10 16:39:50.000000', NULL, 1),
(903679, 103203, 10268, '<td valign="top">I guess there''s an emphasis on that thing in the bottom left corner?  But I''m not sure why.<br/> <br/>People are going to want to see photos of beautiful beaches and shorlines, not decaying buildings (?) in the water, IMO.<br/> <br/>Still a nice scene though.</td>', 'I guess there''s an emphasis on that thing in the bottom left corner?  But I''m not sure why. People are going to want to see photos of beautiful beaches and shorlines, not decaying buildings (?) in the water, IMO. Still a nice scene though.', '2004-09-10 16:44:42.000000', NULL, 1),
(903690, 103052, 4871, '<td valign="top">I love the photograph, but I think you''ll lose point for having the person in the shot. Maybe if they were posed it would be different. Your lighting balance is superb! Did you use shadows/highlights on this shot?</td>', 'I love the photograph, but I think you''ll lose point for having the person in the shot. Maybe if they were posed it would be different. Your lighting balance is superb! Did you use shadows/highlights on this shot?', '2004-09-10 16:52:34.000000', NULL, 1),
(903695, 103162, 4871, '<td valign="top">That''s a magic shot! A little too much on the hue saturation (it really shows on the red flowers) but isn''t much to complain about. Well done!</td>', 'That''s a magic shot! A little too much on the hue saturation (it really shows on the red flowers) but isn''t much to complain about. Well done!', '2004-09-10 16:57:41.000000', NULL, 1),
(903696, 103163, 4871, '<td valign="top">Yep, winner in my books!!! Beautiful! Amazing! I wish I took it! I wish I was there!!! Did you use filters for this or was it done in post?</td>', 'Yep, winner in my books!!! Beautiful! Amazing! I wish I took it! I wish I was there!!! Did you use filters for this or was it done in post?', '2004-09-10 16:59:02.000000', NULL, 1),
(903697, 102416, 4871, '<td valign="top">Amazing shot! I hope this pic does well. I LOVE the cloud formations!</td>', 'Amazing shot! I hope this pic does well. I LOVE the cloud formations!', '2004-09-10 17:00:05.000000', NULL, 1),
(903699, 102295, 15129, '<td valign="top">I would have given it a 10 because it is so gorgeous--very simple but evocative. However the edge of the grass on the side facing the girls seems to be too sharply cut off--it looks artificially tweaked. This might be what you were going for though. It is good.</td>', 'I would have given it a 10 because it is so gorgeous--very simple but evocative. However the edge of the grass on the side facing the girls seems to be too sharply cut off--it looks artificially tweaked. This might be what you were going for though. It is good.', '2004-09-10 17:01:53.000000', NULL, 1),
(903708, 102774, 4871, '<td valign="top">You''ve taken this at the perfect time of day and the colors are sensational. My suggestion would be to have this shot without the wall - I don''t think it adds much to your image.</td>', 'You''ve taken this at the perfect time of day and the colors are sensational. My suggestion would be to have this shot without the wall - I don''t think it adds much to your image.', '2004-09-10 17:12:39.000000', NULL, 1),
(903716, 102979, 4871, '<td valign="top">I really like this image, but when my eye was looking for a catching point it was led to the boat hook - and it doesn''t add as a catching point to your image. If there had have been a boat that was moored to it I would have rated it much higher. You''ve also got a bit of a slant on your image.</td>', 'I really like this image, but when my eye was looking for a catching point it was led to the boat hook - and it doesn''t add as a catching point to your image. If there had have been a boat that was moored to it I would have rated it much higher. You''ve also got a bit of a slant on your image.', '2004-09-10 17:17:50.000000', NULL, 1),
(903719, 101772, 4871, '<td valign="top">Very ''olden day''. I like it! Great shot.</td>', 'Very ''olden day''. I like it! Great shot.', '2004-09-10 17:19:13.000000', NULL, 1),
(903721, 103042, 4871, '<td valign="top">It made me laugh! The balloon on the right reminded me of pac-man! Don''t ask me why :)</td>', 'It made me laugh! The balloon on the right reminded me of pac-man! Don''t ask me why :)', '2004-09-10 17:20:05.000000', NULL, 1),
(903733, 102007, 3102, '<td valign="top">My favorite of the challenge, and my only 10!  I really like the shades of blue, and how they contrast with the orange ground.  Congrats on a spectacular image!</td>', 'My favorite of the challenge, and my only 10!  I really like the shades of blue, and how they contrast with the orange ground.  Congrats on a spectacular image!', '2004-09-10 17:30:41.000000', NULL, 1),
(903735, 103086, 3102, '<td valign="top">Wow -- well done!  I was in San Diego a couple months back, but didn''t have a chance to check out the park, although several local folks had strongly recommended it.  This is quite a cool shot -- lovely sky!</td>', 'Wow -- well done!  I was in San Diego a couple months back, but didn''t have a chance to check out the park, although several local folks had strongly recommended it.  This is quite a cool shot -- lovely sky!', '2004-09-10 17:32:02.000000', NULL, 1),
(903740, 103074, 3102, '<td valign="top">Very nice indeed!  I like the way the path fades off to the distance, and the way the trees are so evenly spaced.  Well done!</td>', 'Very nice indeed!  I like the way the path fades off to the distance, and the way the trees are so evenly spaced.  Well done!', '2004-09-10 17:33:28.000000', NULL, 1),
(903745, 103217, 3102, '<td valign="top">Boy, not too many people rent a helicopter just to get a DPC shot!  :)  Very nice shot -- I like it a lot!  It looks just a teensy bit over-saturated to my eye, but I still love the vantage point and hope to get out there again someday.</td>', 'Boy, not too many people rent a helicopter just to get a DPC shot!  :)  Very nice shot -- I like it a lot!  It looks just a teensy bit over-saturated to my eye, but I still love the vantage point and hope to get out there again someday.', '2004-09-10 17:35:47.000000', NULL, 1),
(903748, 102350, 3102, '<td valign="top">If you look up "quaint" in the dictionary, this is probably the image that will accompany the definition!  Looks like a wonderful place.  Great shot.</td>', 'If you look up "quaint" in the dictionary, this is probably the image that will accompany the definition!  Looks like a wonderful place.  Great shot.', '2004-09-10 17:36:32.000000', NULL, 1),
(903752, 102741, 715, '<td valign="top">..... de Kinderdijk :)<br/>Nice composition and I like the way the mills are lighted by the sun.</td>', '..... de Kinderdijk :)Nice composition and I like the way the mills are lighted by the sun.', '2004-09-10 17:39:17.000000', NULL, 1),
(903755, 103141, 3102, '<td valign="top">Quite a dramatic sky!  Nicely done, considering you still managed to get the monument well-exposed.  I was hoping to get a similar shot when I was there last winter, but the pool was empty at the time.</td>', 'Quite a dramatic sky!  Nicely done, considering you still managed to get the monument well-exposed.  I was hoping to get a similar shot when I was there last winter, but the pool was empty at the time.', '2004-09-10 17:42:04.000000', NULL, 1),
