(904878, 103262, 19421, '<td valign="top">Great colors.</td>', 'Great colors.', '2004-09-11 16:48:58.000000', NULL, 1),
(904880, 102350, 4517, '<td valign="top">I really like this, looks like a model village. Perfect light and colour except for the sky which looks a little odd. Maybe a simple thin black border would be better but still a 10 from me and in my favorites.</td>', 'I really like this, looks like a model village. Perfect light and colour except for the sky which looks a little odd. Maybe a simple thin black border would be better but still a 10 from me and in my favorites.', '2004-09-11 16:49:41.000000', NULL, 1),
