INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(907669, 102518, 8860, '<td valign="top">Excellent result - deservedly.</td>', 'Excellent result - deservedly.', '2004-09-13 13:24:53.000000', NULL, 0),
(907678, 102350, 8005, '<td valign="top">I want to know who the four goofballs were that gave you scores below a 5. I apologize for not voting on this challenge but I would have given you a high score if I did. Sometimes life gets in the way of voting.</td>', 'I want to know who the four goofballs were that gave you scores below a 5. I apologize for not voting on this challenge but I would have given you a high score if I did. Sometimes life gets in the way of voting.', '2004-09-13 13:27:29.000000', NULL, 0),
(907682, 103255, 8860, '<td valign="top">Well done - a top result. Love the composition and the wistful glint of the sun. I think I''d have cloned out the small patch of orange at the bottom - or lifted the detail of the area more (but that''s nitpicking).</td>', 'Well done - a top result. Love the composition and the wistful glint of the sun. I think I''d have cloned out the small patch of orange at the bottom - or lifted the detail of the area more (but that''s nitpicking).', '2004-09-13 13:31:02.000000', NULL, 0),
(907683, 103238, 8860, '<td valign="top">Well there we are - you see John you should have taken a nice pretty little stock shot!  <br/>; )<br/> <br/>This way too cool.</td>', 'Well there we are - you see John you should have taken a nice pretty little stock shot!  ; ) This way too cool.', '2004-09-13 13:33:45.000000', NULL, 0),
(907689, 102350, 26482, '<td valign="top">Very nice indeed... and I''m from England!<br/> <br/>:)<br/> <br/>Congratulations...<br/> <br/>:)<br/> <br/>D.</td>', 'Very nice indeed... and I''m from England! :) Congratulations... :) D.', '2004-09-13 13:36:37.000000', NULL, 0),
(907697, 102117, 8860, '<td valign="top">Deeply underrated shot.</td>', 'Deeply underrated shot.', '2004-09-13 13:40:24.000000', NULL, 0),
(907700, 103052, 8860, '<td valign="top">Isn''t Yosemite amazing? I fell in love with the place - that view out of the tunnel... stunning.</td>', 'Isn''t Yosemite amazing? I fell in love with the place - that view out of the tunnel... stunning.', '2004-09-13 13:41:59.000000', NULL, 0),
(907709, 103240, 8860, '<td valign="top">Despite my commment (which perhaps seems more negative than intended) this was very underrated. <br/> <br/>The tones and DOF are marvellous though.</td>', 'Despite my commment (which perhaps seems more negative than intended) this was very underrated.  The tones and DOF are marvellous though.', '2004-09-13 13:47:25.000000', NULL, 0),
(907726, 103051, 9763, '<td valign="top">I love the colors and how the people actually add color to the photo and show some perspective too!  You can really feel the expansiveness of the beach and sky with them in the photo!  <br/> <br/>Very nice job!!!!  I am happy that 3 chose this as a 10 and that you got NO 1s or 2s!!!!  Keep up the great work!</td>', 'I love the colors and how the people actually add color to the photo and show some perspective too!  You can really feel the expansiveness of the beach and sky with them in the photo!   Very nice job!!!!  I am happy that 3 chose this as a 10 and that you got NO 1s or 2s!!!!  Keep up the great work!', '2004-09-13 13:54:20.000000', NULL, 0),
(907727, 101995, 6771, '<td valign="top">ROFL!  You Keeeeeeellllllll me Imag!   (C:  But we would have tied if it is only .006 too high!  Then what!?<br/> <br/>THANKS FOR ALL THESE AWESOME COMMENTS!!! Very appreciated, for sure!<br/><br/><i>Message edited by author 2004-09-13 12:58:14.</i></td>', 'ROFL!  You Keeeeeeellllllll me Imag!   (C:  But we would have tied if it is only .006 too high!  Then what!? THANKS FOR ALL THESE AWESOME COMMENTS!!! Very appreciated, for sure!', '2004-09-13 13:54:31.000000', '2004-09-13 13:58:14.000000', 0),
(907754, 101995, 2798, '<td valign="top">Absolutely cracking shot - well done.</td>', 'Absolutely cracking shot - well done.', '2004-09-13 14:06:05.000000', NULL, 0),
(907763, 101818, 2798, '<td valign="top">Very "rough guide" stylee - nice one!</td>', 'Very "rough guide" stylee - nice one!', '2004-09-13 14:12:13.000000', NULL, 0),
(907775, 102168, 3447, '<td valign="top"><br/>Sorry to hear about your $600.  I spent a lot of time at the craps tables of the Flamingo in the early 1950s...and the mob treated us better in those days.  Now we enjoy the restaurants and shows, and avoid gambling since the "profit center" accountants run the casinos.  <br/> <br/>Your Alladin photograph sky fooled several DPCers.<br/>A nice shot, especially sans tripod.</td>', 'Sorry to hear about your $600.  I spent a lot of time at the craps tables of the Flamingo in the early 1950s...and the mob treated us better in those days.  Now we enjoy the restaurants and shows, and avoid gambling since the "profit center" accountants run the casinos.   Your Alladin photograph sky fooled several DPCers.A nice shot, especially sans tripod.', '2004-09-13 14:18:31.000000', NULL, 0),
(907813, 102295, 7778, '<td valign="top">In response to comments requesting post-processing details:<br/> <br/>I used the clone stamp and smudge tools to remove a partial halo of a steering wheel in the very bottom right of the image (the photo was taken during a downpour from inside a car).<br/> <br/>Minute adjustments were made to contrast/brightness (levels) and hues. I used a lighting effect to emphasize the presence of light in the sky (above horizon/top left) and applied smart blur to the entire image. Sharpened (via USM) and resized, as usual.<br/> <br/>The effect so many of you questioned is due to the smart blur filter entirely.<br/> <br/>Whether or not this shot has ''photographic integrity'', I cannot say, because I don''t know what the term, specifically, means. To me, the ''effect'' suits this particular photograph, since the ''irreality'' proliferated by it<br/>replicates the one inherent in the actual scene (confusion of sharpness and unsharpness of objects perceived during a torrent / play of light under such conditions).<br/> <br/>I, decidedly, do not view this image as ''digital art'' (with all its aesthetical connotations), but wish, instead, I could have found a way to render the photo less inclusively sharpened, as I have done and as wagnes has so aptly pointed out.</td>', 'In response to comments requesting post-processing details: I used the clone stamp and smudge tools to remove a partial halo of a steering wheel in the very bottom right of the image (the photo was taken during a downpour from inside a car). Minute adjustments were made to contrast/brightness (levels) and hues. I used a lighting effect to emphasize the presence of light in the sky (above horizon/top left) and applied smart blur to the entire image. Sharpened (via USM) and resized, as usual. The effect so many of you questioned is due to the smart blur filter entirely. Whether or not this shot has ''photographic integrity'', I cannot say, because I don''t know what the term, specifically, means. To me, the ''effect'' suits this particular photograph, since the ''irreality'' proliferated by itreplicates the one inherent in the actual scene (confusion of sharpness and unsharpness of objects perceived during a torrent / play of light under such conditions). I, decidedly, do not view this image as ''digital art'' (with all its aesthetical connotations), but wish, instead, I could have found a way to render the photo less inclusively sharpened, as I have done and as wagnes has so aptly pointed out.', '2004-09-13 14:40:39.000000', NULL, 0),
(907823, 103247, 3447, '<td valign="top"><br/>Great summer clouds, Laurie.  This photograph must be a real shock to our friends in NE cities who may never, ever have seen country without crowds of people, cars and buildings.</td>', 'Great summer clouds, Laurie.  This photograph must be a real shock to our friends in NE cities who may never, ever have seen country without crowds of people, cars and buildings.', '2004-09-13 14:55:28.000000', NULL, 0),
(907831, 101801, 7889, '<td valign="top">Jon - its about bloody time!! Well done matey, great shot.<br/> <br/>Mike<br/> <br/></td>', 'Jon - its about bloody time!! Well done matey, great shot. Mike ', '2004-09-13 15:06:07.000000', NULL, 0),
(907833, 101995, 7889, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Imagineer:</b></div><hr/><i> Obviously the voters gave this 0.006 too many points, but despite that sheer luck - well done anyway!  <br/>; ) </i></td></tr></table> <br/> <br/>Its my fault - I went back through them and bumped this one up!! Great shot, well deserved.<br/> <br/>Mike<br/></td>', 'Originally posted by Imagineer: Obviously the voters gave this 0.006 too many points, but despite that sheer luck - well done anyway!  ; )   Its my fault - I went back through them and bumped this one up!! Great shot, well deserved. Mike', '2004-09-13 15:08:00.000000', NULL, 0),
